// Generated by build.js from data/*.json. Do not edit by hand.
window.DECKS=[{"name":"Common Words I","slug":"common-words-i","series":"Common Words","words":[{"w":"aberration","p":"n.","m":"A departure from what is normal or expected.","e":"Latin <i>aberrare</i>, “to wander away”: <i>ab-</i> (away) + <i>errare</i> (to wander, stray). The same <i>errare</i> gives French <i>errer</i> and English <i>err</i>, <i>error</i>.","f":"aberration","t":"Picture a knight-errant drifting off the road: ab + errer = wandering off the normal path. French already has the word with the same meaning."},{"w":"acrimony","p":"n.","m":"Bitter, sharp ill-feeling, especially in words or a dispute.","e":"Latin <i>acrimonia</i>, “sharpness, pungency”, from <i>acer</i> (sharp, sour). Same root as French <i>âcre</i>, <i>aigre</i> and <i>vinaigre</i> (vin + aigre).","f":"acrimonie, aigreur","t":"Acer → aigre → vinaigre. An acrimonious divorce is a marriage that has turned to vinegar."},{"w":"amalgam","p":"n.","m":"A mixture or blend of different elements.","e":"Medieval Latin <i>amalgama</i>, the alchemists’ word for an alloy of mercury with another metal, probably via Arabic from Greek <i>malagma</i> (a softening paste). Dentists’ silver fillings are still called amalgam.","f":"amalgame (« faire l’amalgame »)","t":"Same word as « faire l’amalgame », lumping things together. Think of the dentist’s filling: several metals fused into one."},{"w":"ambiguous","p":"adj.","m":"Open to more than one interpretation; unclear.","e":"Latin <i>ambiguus</i>, “doubtful, shifting”, from <i>ambigere</i>, “to waver”: <i>ambi-</i> (both ways, around) + <i>agere</i> (to drive, lead).","f":"ambigu","t":"Ambi = both ways, as in ambidextrous. A sentence driving in two directions at once. Identical to French ambigu."},{"w":"ambivalent","p":"adj.","m":"Having mixed or contradictory feelings about something.","e":"A modern coinage: the Swiss psychiatrist Eugen Bleuler built German <i>Ambivalenz</i> in 1910 from Latin <i>ambi-</i> (both) + <i>valentia</i> (strength, from <i>valere</i>, to be strong).","f":"ambivalent, partagé","t":"Ambi + valent = two feelings of equal strength pulling at once. Ambiguous describes a message; ambivalent describes how a person feels."},{"w":"amenable","p":"adj.","m":"Willing to cooperate or be persuaded; open to.","e":"Anglo-French <i>amenable</i>, “able to be led”, from <i>amener</i> (à + <i>mener</i>), from Late Latin <i>minare</i>, “to drive animals by shouting”. First a legal word: answerable to a court.","f":"accommodant, réceptif, disposé à","t":"French amener: an amenable person is easy to « amener » to your view. You can lead them where you want."},{"w":"amorphous","p":"adj.","m":"Without a clear shape, form or structure.","e":"Greek <i>amorphos</i>: <i>a-</i> (without) + <i>morphē</i> (shape, form). Same <i>morphē</i> as in metamorphosis and morphology.","f":"amorphe, informe","t":"A-morph = no shape, a metamorphosis that never finished. French « amorphe » often means listless; in English keep it about shape: an amorphous plan, an amorphous blob."},{"w":"anomalous","p":"adj.","m":"Deviating from what is standard or expected.","e":"Greek <i>anōmalos</i>, “uneven, irregular”: <i>an-</i> (not) + <i>homalos</i> (even, level), related to <i>homos</i> (same).","f":"anormal, anomal (une anomalie)","t":"An-homalos = not level, not the same as the rest. The anomaly is the data point that sticks out of the even line."},{"w":"artful","p":"adj.","m":"Cunning and sly (the usual GRE sense); also skilful.","e":"English <i>art</i> + <i>-ful</i>. <i>Art</i> came through Old French from Latin <i>ars, artis</i> (skill, craft), which also gave <i>artifice</i> and <i>artificial</i>. “Skilful” slid to “crafty” by the 1700s.","f":"rusé, astucieux, habile","t":"Think artifice, not art gallery. The Artful Dodger in Oliver Twist is a pickpocket full of tricks.","x":"2nd meaning"},{"w":"auspicious","p":"adj.","m":"Showing signs of future success; favourable.","e":"Latin <i>auspicium</i>, “divination from birds”: <i>avis</i> (bird) + <i>specere</i> (to look). Roman augurs read the gods’ will in the flight of birds before any big decision.","f":"favorable, de bon augure (« sous de bons auspices »)","t":"« Sous de bons auspices »: picture the Roman priest watching the birds fly the right way. Auspicious = the birds say yes."},{"w":"belie","p":"v.","m":"To give a false impression of; or to show something to be false.","e":"Old English <i>belēogan</i>, “to deceive by lying”: <i>be-</i> + <i>lēogan</i> (to lie). Purely Germanic. The surface “lies about” what is underneath.","f":"démentir, masquer, contredire","t":"Be + lie: the surface tells a lie. “Her calm smile belied her panic” = the smile lied about it."},{"w":"betray","p":"v.","m":"To reveal unintentionally (the GRE sense); also to be disloyal.","e":"Germanic prefix <i>be-</i> + Middle English <i>trayen</i>, from Old French <i>trair</i> (now <i>trahir</i>), from Latin <i>tradere</i>, “to hand over”.","f":"trahir (« sa voix trahissait sa nervosité »)","t":"Exactly like French « trahir son émotion »: your face hands over (tradere) the secret without your permission.","x":"2nd meaning"},{"w":"calumny","p":"n.","m":"A false statement made to damage someone’s reputation; slander.","e":"Latin <i>calumnia</i>, “trickery, false accusation”, from <i>calvi</i> (to deceive). Came into English through French <i>calomnie</i>.","f":"calomnie","t":"Same word as « calomnie », and the old saying: « Calomniez, calomniez, il en restera toujours quelque chose. »"},{"w":"castigate","p":"v.","m":"To criticise or reprimand severely.","e":"Latin <i>castigare</i>, “to correct, punish”, literally “to make pure”: <i>castus</i> (pure, chaste) + <i>agere</i> (to drive). The same verb became Old French <i>chastier</i>, now <i>châtier</i>, which English borrowed again as chastise.","f":"fustiger, réprimander, châtier","t":"Castigate and chastise are twins, both from castigare → châtier. « Qui aime bien châtie bien. »"},{"w":"censure","p":"n. / v.","m":"Formal, severe disapproval; to criticise officially.","e":"Latin <i>censura</i>, the office of the Roman <i>censor</i> (from <i>censere</i>, to assess). Censors ran the census and also judged citizens’ morals, publicly marking the disgraced.","f":"blâme, censure (« motion de censure »)","t":"Think « motion de censure » at the Assemblée: an official vote of disapproval. Censure = formal blame. Cutting out content is censor."},{"w":"chastise","p":"v.","m":"To scold or punish severely.","e":"Middle English <i>chastisen</i>, from <i>chasten</i>, from Old French <i>chastier</i> (modern <i>châtier</i>), from Latin <i>castigare</i>, “to make pure”.","f":"châtier, réprimander","t":"Chastise sounds like châtier because it is châtier. The twin of castigate."},{"w":"commensurate","p":"adj.","m":"In proportion to; corresponding in size or degree.","e":"Late Latin <i>commensuratus</i>: <i>com-</i> (together) + <i>mensurare</i> (to measure), from <i>mensura</i> (measure).","f":"proportionné à, à la mesure de","t":"Com + mesure = measured together. “Salary commensurate with experience” = à la mesure de votre expérience."},{"w":"demur","p":"v.","m":"To raise objections or show reluctance.","e":"Old French <i>demorer</i>, “to linger, delay” (modern <i>demeurer</i>), from Latin <i>demorari</i>, from <i>mora</i> (delay, as in moratorium). Lawyers turned “delay” into a formal objection, the demurrer.","f":"émettre des réserves, objecter, hésiter","t":"Demur = demeurer: you stay put instead of going along. Don’t confuse with demure (shy, modest).","x":"Look-alike"},{"w":"disinterested","p":"adj.","m":"Impartial, with no personal stake (not “uninterested”).","e":"<i>dis-</i> (not) + interested, from Latin <i>interesse</i>, “to be between, to matter”: <i>inter</i> + <i>esse</i>. Here “interest” means a stake, as in conflict of interest.","f":"désintéressé, impartial","t":"Same as French « désintéressé »: a referee with nothing to gain. A disinterested judge is good; an uninterested judge is asleep.","x":"2nd meaning"},{"w":"egregious","p":"adj.","m":"Outstandingly bad; shocking.","e":"Latin <i>egregius</i>, “standing out from the flock”: <i>e/ex</i> (out of) + <i>grex, gregis</i> (flock). It first meant “distinguished”; ironic use in the 1500s made the bad sense win.","f":"flagrant, énorme, grossier (« une erreur grossière »)","t":"Ex grege: the sheep that stands out of the flock, for the wrong reason. Same grex as gregarious and grégaire."},{"w":"enervate","p":"v.","m":"To weaken; drain of energy (not “to annoy” or “energise”).","e":"Latin <i>enervare</i>, “to remove the sinews”: <i>e-</i> (out) + <i>nervus</i> (sinew, tendon). Old French <i>énerver</i> meant the same before it shifted to “irritate”.","f":"affaiblir, épuiser, amollir (≠ énerver)","t":"Remember « les Énervés de Jumièges », the two princes of legend whose tendons were cut: énervés in the old sense, drained of strength. That is the English meaning.","x":"Faux ami"},{"w":"equivocal","p":"adj.","m":"Ambiguous, often deliberately; open to two readings.","e":"Late Latin <i>aequivocus</i>, “of identical sound”: <i>aequus</i> (equal) + <i>vox, vocis</i> (voice). Two meanings with an equal voice.","f":"équivoque","t":"Same as « équivoque »: two meanings speak equally loud, so you can’t tell which is meant. To equivocate = to dodge with double-meaning words."},{"w":"extant","p":"adj.","m":"Still in existence; surviving.","e":"Latin <i>exstantem</i>, from <i>exstare</i>, “to stand out, be visible”: <i>ex</i> + <i>stare</i> (to stand).","f":"existant, qui subsiste, encore conservé","t":"Ex-stare = still standing. “The oldest extant manuscript” is the one still standing after the others were lost. Opposite: extinct."},{"w":"frugal","p":"adj.","m":"Sparing and economical with money or food.","e":"Latin <i>frugalis</i>, from <i>frugi</i> (useful, thrifty), from <i>frux, frugis</i> (fruit, produce). A frugal man made good use of his harvest.","f":"frugal, économe (« un repas frugal »)","t":"Identical to « un repas frugal ». Frux = fruit: living on what your own trees give you."},{"w":"galvanize","p":"v.","m":"To shock or excite someone into action.","e":"Named after Luigi Galvani (1737–1798), the Bologna physician whose dissected frog legs twitched when touched with metals: “animal electricity”. The zinc-coating sense came later, from galvanic cells.","f":"galvaniser","t":"Picture Galvani’s frog leg jumping when the current hits it. To galvanize a team = jolt it into motion. Same in French."},{"w":"gregarious","p":"adj.","m":"Fond of company; sociable.","e":"Latin <i>gregarius</i>, “of the flock”, from <i>grex, gregis</i> (flock, herd).","f":"sociable, liant (« grégaire » is more pejorative)","t":"Grex = the flock: a gregarious person loves being in the herd. In English it’s a compliment, unlike « l’instinct grégaire »."},{"w":"harangue","p":"n. / v.","m":"A long, aggressive or pompous speech; to lecture forcefully.","e":"Middle French <i>harangue</i>, from Old Italian <i>aringa</i> (public speech), from <i>aringo</i> (public square), from a Germanic word for a ring of people at an assembly (compare English <i>ring</i>).","f":"harangue, haranguer","t":"Same as « haranguer la foule ». Picture a Germanic chief in the middle of a ring of warriors, shouting at them."},{"w":"iconoclast","p":"n.","m":"A person who attacks cherished beliefs or institutions.","e":"Greek <i>eikōn</i> (image) + <i>klastēs</i> (breaker), from <i>klan</i> (to break). First the Byzantine iconoclasts of the 8th–9th centuries, who smashed religious images.","f":"iconoclaste","t":"Icon-breaker: a monk smashing holy images. Today it’s someone smashing sacred ideas, like the founder who breaks every rule of an industry."},{"w":"impertinent","p":"adj.","m":"Rude, disrespectful; also (older sense) not relevant.","e":"Latin <i>impertinentem</i>, “not belonging”: <i>in-</i> (not) + <i>pertinere</i> (to relate to). First “irrelevant”, then “meddling in what doesn’t concern you”, hence “rude”.","f":"impertinent, insolent; (ou) non pertinent","t":"Both meanings come from “not pertinent”: either irrelevant, or poking into things that are none of your business.","x":"2nd meaning"},{"w":"ingenuous","p":"adj.","m":"Innocent, naive, candid (not “ingenious”).","e":"Latin <i>ingenuus</i>, “native, freeborn”, hence “noble, frank”: <i>in-</i> + <i>gignere</i> (to beget). A freeborn person had nothing to hide.","f":"ingénu, candide, naïf","t":"Ingenuous = ingénu, like Voltaire’s L’Ingénu. Ingenious (with an i) is clever; disingenuous is fake-innocent.","x":"Look-alike"},{"w":"innocuous","p":"adj.","m":"Harmless; inoffensive.","e":"Latin <i>innocuus</i>: <i>in-</i> (not) + <i>nocuus</i> (harmful), from <i>nocere</i> (to harm). Same family as French <i>nuire</i>, <i>nocif</i> and <i>innocent</i>.","f":"inoffensif, anodin","t":"In + nocif = not nocif. An innocuous remark does no harm at all."},{"w":"intimate","p":"v.","m":"To hint or suggest indirectly (the GRE verb sense).","e":"Late Latin <i>intimare</i>, “to make known, announce”, from <i>intimus</i> (inmost): putting an idea into someone’s innermost thoughts.","f":"laisser entendre, insinuer, suggérer (≠ intimer)","t":"The verb, said “inti-MATE”, slips an idea into someone’s mind without saying it. Not French « intimer un ordre », which is the opposite of subtle.","x":"2nd meaning"},{"w":"involved","p":"adj.","m":"Complicated, intricate (the GRE sense).","e":"Latin <i>involvere</i>, “to roll into, wrap up”: <i>in-</i> + <i>volvere</i> (to roll). Something rolled in many layers is hard to unwrap.","f":"compliqué, alambiqué, complexe","t":"Picture a scroll rolled up on itself: an involved argument has to be unrolled layer by layer. Think « alambiqué ».","x":"2nd meaning"},{"w":"laconic","p":"adj.","m":"Using very few words; terse.","e":"Greek <i>Lakōnikos</i>, “of Laconia”, the region around Sparta. Spartans were famous for blunt brevity.","f":"laconique","t":"Philip II of Macedon warned Sparta: “If I invade Laconia, I will destroy you.” The Spartans replied with one word: “If.”"},{"w":"maintain","p":"v.","m":"To assert, claim firmly (the GRE sense).","e":"Old French <i>maintenir</i>, from Latin <i>manu tenere</i>, “to hold in the hand”.","f":"maintenir, affirmer, soutenir (« je maintiens que… »)","t":"Exactly French « je maintiens que c’est faux »: you hold your position in your hand and won’t let go.","x":"2nd meaning"},{"w":"mercurial","p":"adj.","m":"Subject to sudden, unpredictable changes of mood.","e":"Latin <i>mercurialis</i>, “of Mercury”: the swift messenger god, the fast planet, and quicksilver, the liquid metal that never sits still. Astrologers said people born under Mercury were volatile.","f":"versatile, lunatique, d’humeur changeante","t":"Picture a drop of mercury (vif-argent) skittering across a table, impossible to pin down. A mercurial boss changes mood that fast."},{"w":"parochial","p":"adj.","m":"Narrow in outlook; limited to local concerns.","e":"Late Latin <i>parochialis</i>, from <i>parochia</i> (parish), from Greek <i>paroikia</i>: <i>para</i> (beside) + <i>oikos</i> (house). Thinking that stops at the parish boundary.","f":"borné, provincial (« esprit de clocher »)","t":"Parochial = paroissial. « L’esprit de clocher »: someone who can’t see past their own village church tower."},{"w":"parsimonious","p":"adj.","m":"Extremely unwilling to spend money; stingy.","e":"Latin <i>parsimonia</i> (thrift), from <i>parcere</i>, “to spare, save”.","f":"parcimonieux, pingre, radin","t":"« Avec parcimonie »: coins handed out one by one. Stronger than frugal: frugal is a virtue, parsimonious is stingy."},{"w":"prevaricate","p":"v.","m":"To speak evasively; to dodge the truth.","e":"Latin <i>praevaricari</i>, “to walk crookedly, straddle”: <i>prae</i> + <i>varicare</i> (to straddle), from <i>varus</i> (bow-legged). In Roman law, a prosecutor secretly colluding with the defence.","f":"tergiverser, user de faux-fuyants (≠ prévariquer)","t":"Picture someone bow-legged, zig-zagging so they never walk straight to the truth. Tergiverser.","x":"Faux ami"},{"w":"prodigal","p":"adj. / n.","m":"Wastefully extravagant; someone who squanders.","e":"Latin <i>prodigus</i> (wasteful), from <i>prodigere</i>, “to drive away, squander”: <i>pro-</i> (forth) + <i>agere</i> (to drive).","f":"prodigue (« l’enfant prodigue »)","t":"The prodigal son of the parable, « l’enfant prodigue », who blew his inheritance. Not to be confused with prodigy (a genius).","x":"Look-alike"},{"w":"profligate","p":"adj.","m":"Recklessly wasteful; also dissolute, immoral.","e":"Latin <i>profligatus</i>, “ruined, dissolute”, from <i>profligare</i>, “to strike down”: <i>pro-</i> + <i>fligere</i> (to strike), as in inflict and conflict.","f":"dépensier, dissipateur, débauché","t":"Profligate = prodigal who also parties. Pro + fligere: knocking down your own fortune and morals blow by blow."},{"w":"qualify","p":"v.","m":"To limit or modify a statement; add reservations (GRE sense).","e":"Medieval Latin <i>qualificare</i>, “to give a quality to”: <i>qualis</i> (of what kind) + <i>facere</i> (to make).","f":"nuancer, apporter une réserve, tempérer","t":"Think « nuancer son propos ». A qualified endorsement is a yes with an asterisk.","x":"2nd meaning"},{"w":"restive","p":"adj.","m":"Restless, impatient, resisting control.","e":"Old French <i>restif</i> (now <i>rétif</i>), “stationary, balky”, from <i>rester</i>, Latin <i>restare</i> (to stay). Used first of horses that refused to go forward; their stamping and fidgeting took over the meaning.","f":"agité, nerveux, rétif","t":"Picture « un cheval rétif », refusing to move while stamping and pulling at the reins. A restive crowd is losing patience."},{"w":"undermine","p":"v.","m":"To weaken gradually or secretly.","e":"Middle English <i>under</i> + <i>mine</i> (from Old French <i>miner</i>). Besiegers dug tunnels under castle walls, propped them with timber, then burned the props so the wall fell.","f":"saper, miner, ébranler","t":"Same image as French « saper le moral »: digging under the wall until it collapses."},{"w":"upbraid","p":"v.","m":"To scold or reproach severely.","e":"Old English <i>upbregdan</i>, “to throw up against”: <i>up</i> + <i>bregdan</i> (to move quickly, weave; the source of braid). You throw someone’s faults back at them.","f":"réprimander, sermonner, faire des reproches","t":"Up + braid: you hurl the reproach up into their face. It sounds harsh because it is."},{"w":"venality","p":"n.","m":"Openness to bribery; corruption.","e":"Latin <i>venalis</i>, “for sale”, from <i>venum</i> (sale), which also gave <i>vendere</i>, to sell (<i>venum dare</i>).","f":"vénalité, corruption","t":"Think « la vénalité des offices » under the Ancien Régime, when judges bought their posts. Venal = for sale. Venial is a small, forgivable sin.","x":"Look-alike"},{"w":"venerate","p":"v.","m":"To regard with deep respect; revere.","e":"Latin <i>venerari</i>, “to worship, revere”, related to <i>Venus</i> (love, desire).","f":"vénérer","t":"Identical to « vénérer ». Picture bowing before a statue of Venus."},{"w":"veracious","p":"adj.","m":"Truthful; accurate.","e":"Latin <i>verax, veracis</i> (truthful), from <i>verus</i> (true).","f":"véridique (« la véracité »)","t":"Véracité = truthfulness. Don’t confuse with voracious (hungry): veracious = vrai.","x":"Look-alike"},{"w":"vindicate","p":"v.","m":"To clear of blame; to prove right.","e":"Latin <i>vindicare</i>, “to claim, avenge, set free”, from <i>vindex</i> (claimant, avenger). The same verb gave French <i>venger</i> and <i>revendiquer</i>.","f":"disculper, justifier, donner raison à","t":"Vindicate = venger: being proved right is your revenge. When the data vindicated her, she was avenged."},{"w":"wanting","p":"adj.","m":"Lacking; not good enough.","e":"Old Norse <i>vanta</i>, “to lack”, brought by Viking settlers. “Want” meant “lack” long before it meant “desire”.","f":"insuffisant, déficient, qui fait défaut","t":"From the Book of Daniel: “weighed in the balances, and found wanting” (« pesé dans la balance et trouvé léger »).","x":"2nd meaning"}]},{"name":"Common Words II","slug":"common-words-ii","series":"Common Words","words":[{"w":"aesthete","p":"n.","m":"A person with a refined appreciation of art and beauty (sometimes excessive).","e":"Coined in 19th-century English from Greek <i>aisthētēs</i>, “one who perceives”, from <i>aisthanesthai</i> (to perceive, feel). Tied to Oscar Wilde’s Aesthetic movement and “art for art’s sake”.","f":"esthète","t":"Picture Oscar Wilde with a lily and a velvet jacket. Aesthete = the person; aesthetic = the quality."},{"w":"aesthetic","p":"adj. / n.","m":"Concerned with beauty or artistic taste.","e":"Greek <i>aisthētikos</i>, “of sense perception”, from <i>aisthanesthai</i> (to perceive). The German philosopher Baumgarten gave it the meaning “theory of taste” in the 1700s.","f":"esthétique","t":"Anesthetic = no feeling. Aesthetic = what your senses feel, especially beauty."},{"w":"apathetic","p":"adj.","m":"Showing no interest, enthusiasm or concern.","e":"Greek <i>apatheia</i>: <i>a-</i> (without) + <i>pathos</i> (feeling, suffering). For the Stoics apatheia was an ideal; in English it became indifference.","f":"apathique, indifférent","t":"A-pathos = no feeling, the opposite of sympathy and passion. Same as French apathique."},{"w":"audacious","p":"adj.","m":"Bold and daring; sometimes shamelessly so.","e":"Latin <i>audax, audacis</i> (bold), from <i>audere</i> (to dare).","f":"audacieux","t":"Danton in 1792: « De l’audace, encore de l’audace, toujours de l’audace ! » Audacious can praise or condemn."},{"w":"banal","p":"adj.","m":"Lacking originality; trite.","e":"French <i>banal</i>, from the feudal <i>ban</i> (the lord’s jurisdiction; a Frankish word). The <i>four banal</i> and <i>moulin banal</i> were the lord’s oven and mill every villager had to use: “common to all” became “commonplace”.","f":"banal","t":"Picture the village four banal: everyone bakes in the same oven, so every loaf looks the same."},{"w":"bucolic","p":"adj.","m":"Relating to the pleasant side of country life; pastoral.","e":"Greek <i>boukolikos</i>, “of herdsmen”, from <i>boukolos</i> (cowherd): <i>bous</i> (ox) + <i>-kolos</i> (tending). Virgil’s <i>Bucolics</i> made it a literary genre.","f":"bucolique, champêtre","t":"Bous = ox. A cowherd lounging in a meadow, Virgil-style. Same as French bucolique."},{"w":"chortle","p":"v. / n.","m":"To laugh in a gleeful, breathy way.","e":"Coined by Lewis Carroll in <i>Through the Looking-Glass</i> (1871) as a blend of chuckle + snort.","f":"glousser, rire de contentement","t":"Chuckle + snort = chortle. The satisfied, slightly smug laugh after winning an argument."},{"w":"concede","p":"v.","m":"To admit something is true, often reluctantly; to yield.","e":"Latin <i>concedere</i>, “to give way”: <i>com-</i> + <i>cedere</i> (to go, yield).","f":"concéder, admettre, céder","t":"Concéder: same word. You concede a point in an argument, or concede defeat in an election."},{"w":"conspicuous","p":"adj.","m":"Clearly visible; attracting attention.","e":"Latin <i>conspicuus</i> (visible), from <i>conspicere</i>, “to look at closely”: <i>com-</i> + <i>specere</i> (to look), the root of spectacle and perspicace.","f":"voyant, manifeste, ostensible","t":"Veblen’s “conspicuous consumption” (1899): the logo-covered handbag bought to be seen. Conspicuous = made to be looked at."},{"w":"cryptic","p":"adj.","m":"Mysterious; obscure in meaning.","e":"Late Latin <i>crypticus</i>, from Greek <i>kryptikos</i>, from <i>kryptos</i> (hidden). Same root as crypt and cryptography.","f":"énigmatique, sibyllin","t":"Kryptos = hidden, like a crypt under a church. A cryptic message keeps its meaning underground."},{"w":"culminate","p":"v.","m":"To reach the highest point or climax.","e":"Late Latin <i>culminare</i> (to crown), from <i>culmen</i> (summit). Astronomers used it for a star reaching its highest point in the sky.","f":"culminer, aboutir","t":"« Le point culminant » = the summit. A career that culminates in the CEO role reaches its peak there."},{"w":"culpability","p":"n.","m":"Responsibility for a fault or wrong; blameworthiness.","e":"Latin <i>culpabilis</i> (blameworthy), from <i>culpa</i> (fault, blame).","f":"culpabilité","t":"Mea culpa = my fault. Culpability = culpabilité."},{"w":"decorous","p":"adj.","m":"In keeping with good taste and propriety; polite.","e":"Latin <i>decorus</i> (becoming, proper), from <i>decor</i> (seemliness), from <i>decere</i> (to be fitting). Same root as decorum and décent.","f":"bienséant, convenable, digne","t":"Think « le décorum »: decorous behaviour respects decorum. Nothing to do with decorations."},{"w":"deferential","p":"adj.","m":"Showing respect and humble submission.","e":"From deference, French <i>déférence</i>, from <i>déférer</i> (to yield to), Latin <i>deferre</i>: <i>de-</i> + <i>ferre</i> (to carry).","f":"déférent, respectueux","t":"Same as « par déférence ». A deferential junior defers to the partner’s judgment."},{"w":"dictatorial","p":"adj.","m":"Domineering; imposing one’s will on others.","e":"Latin <i>dictator</i>, from <i>dictare</i> (to say repeatedly, prescribe). In Rome a dictator was a magistrate given absolute power for six months in an emergency.","f":"dictatorial, autoritaire, tyrannique","t":"The one who dictates. A dictatorial manager dictates and nobody else gets to speak."},{"w":"didactic","p":"adj.","m":"Intended to teach, often in a preachy or moralising way.","e":"Greek <i>didaktikos</i>, “apt at teaching”, from <i>didaskein</i> (to teach).","f":"didactique; moralisateur","t":"Same as « didactique ». On the GRE it often stings a little: a didactic novel lectures you."},{"w":"diffident","p":"adj.","m":"Shy; lacking self-confidence.","e":"Latin <i>diffidentem</i>, from <i>diffidere</i>, “to mistrust”: <i>dis-</i> (not) + <i>fidere</i> (to trust), as in fidèle and confiance. First it meant distrusting others; now, distrusting yourself.","f":"timide, qui manque d’assurance","t":"Dis + fidere = no trust. Défiance is mistrust of others; diffidence is mistrust of yourself. Opposite: confident (con + fidere)."},{"w":"dogmatic","p":"adj.","m":"Asserting opinions as undeniably true; inflexible.","e":"Greek <i>dogmatikos</i>, from <i>dogma</i> (opinion, decree), from <i>dokein</i> (to seem, think).","f":"dogmatique","t":"Dogma = a decree that can’t be questioned. Same as French dogmatique."},{"w":"engender","p":"v.","m":"To cause or give rise to.","e":"Old French <i>engendrer</i>, from Latin <i>ingenerare</i>: <i>in-</i> + <i>generare</i> (to beget), from <i>genus</i> (birth, kind).","f":"engendrer","t":"Same as « engendrer ». A policy engenders resentment the way parents engender children."},{"w":"entrenched","p":"adj.","m":"Firmly established and hard to change.","e":"<i>en-</i> + trench, from Old French <i>trenche</i> (a cut, a ditch), from <i>trenchier</i> (now <i>trancher</i>), probably from Latin <i>truncare</i> (to cut off).","f":"ancré, enraciné, retranché","t":"Picture WWI soldiers dug into their tranchées for years. An entrenched belief is dug in and won’t move."},{"w":"eschew","p":"v.","m":"To deliberately avoid; abstain from.","e":"Old French <i>eschiver</i> (later <i>esquiver</i>), from Frankish <i>skiuhan</i> (to fear, shun). A cousin of English shy and German <i>scheuen</i>.","f":"éviter, esquiver, s’abstenir de","t":"Eschew = esquiver. Say it “es-CHOO” and picture dodging a sneeze. To eschew meat = to avoid it on principle."},{"w":"exacerbate","p":"v.","m":"To make a problem worse.","e":"Latin <i>exacerbare</i> (to irritate, make harsh): <i>ex-</i> + <i>acerbus</i> (harsh, bitter).","f":"exacerber, aggraver","t":"Acerbus = acerbe. Pouring something bitter on a wound: same as « exacerber »."},{"w":"fortuitous","p":"adj.","m":"Happening by chance (not necessarily lucky).","e":"Latin <i>fortuitus</i> (happening by chance), from <i>fors</i> (chance), the root of Fortuna.","f":"fortuit (« une rencontre fortuite »)","t":"« Une rencontre fortuite » = a chance meeting. On the GRE, fortuitous means accidental, not fortunate.","x":"Look-alike"},{"w":"frivolous","p":"adj.","m":"Not serious; silly, trivial.","e":"Latin <i>frivolus</i> (silly, empty, worthless), possibly from <i>friare</i> (to crumble).","f":"frivole","t":"Identical to frivole. Things that crumble into nothing: a frivolous lawsuit has no substance."},{"w":"gainsay","p":"v.","m":"To deny or contradict.","e":"Middle English: <i>gain-</i>, “against” (Old English <i>gegn</i>, as in again and against) + say. Purely Germanic.","f":"contredire, nier","t":"Gain = against: to say against. “No one can gainsay her results” = no one can contradict them."},{"w":"gall","p":"n.","m":"Bold, impudent behaviour; nerve. (Also bitterness, bile.)","e":"Old English <i>gealla</i> (bile), from an Indo-European root for yellow-green; related to Greek <i>cholē</i> (bile, as in cholera and mélancolie). Bitterness became audacity in 19th-century American slang.","f":"culot, toupet; fiel (la bile)","t":"The gall bladder holds bitter bile. Having the gall to ask = avoir le culot. To gall someone = to irritate them."},{"w":"germane","p":"adj.","m":"Relevant to the subject at hand.","e":"A variant of <i>german</i>, “of the same parents”, from Latin <i>germanus</i> (full brother or sister). Closely related, hence relevant.","f":"pertinent, en rapport avec","t":"Cousin germain! A germane point is closely related to the topic, like a first cousin."},{"w":"glut","p":"n. / v.","m":"An excessive supply; to oversupply.","e":"Middle English <i>glotten</i> (to swallow greedily), from Old French <i>gloutir</i>, from Latin <i>gluttire</i> (to swallow). Same root as glouton and engloutir.","f":"surabondance, excédent, saturation","t":"Glouton + engloutir: a market so stuffed it can’t swallow any more. A glut of oil = prices collapse."},{"w":"gossamer","p":"n. / adj.","m":"Extremely light, thin and delicate; fine spider silk.","e":"Middle English <i>gossomer</i>, probably “goose summer”: the warm spell in late autumn (St Martin’s summer) when geese were eaten and fine cobwebs floated over the fields.","f":"fils de la Vierge; arachnéen, vaporeux","t":"« Les fils de la Vierge »: threads of spider silk drifting over a field in an Indian summer. Gossamer = that light."},{"w":"impudent","p":"adj.","m":"Not showing due respect; shamelessly bold.","e":"Latin <i>impudentem</i> (shameless): <i>in-</i> (not) + <i>pudens</i> (modest), from <i>pudere</i> (to feel shame).","f":"impudent, effronté, insolent","t":"In + pudeur = no shame. Same as French impudent, and close to gall and impertinent."},{"w":"incisive","p":"adj.","m":"Sharp and clear-thinking; going straight to the point.","e":"Medieval Latin <i>incisivus</i>, from <i>incidere</i>, “to cut into”: <i>in-</i> + <i>caedere</i> (to cut).","f":"incisif, tranchant, pénétrant","t":"Your incisives are the cutting teeth. An incisive question cuts straight to the core of the problem."},{"w":"inexorable","p":"adj.","m":"Impossible to stop or prevent; relentless.","e":"Latin <i>inexorabilis</i>: <i>in-</i> (not) + <i>exorabilis</i> (moved by pleading), from <i>exorare</i>: <i>ex-</i> + <i>orare</i> (to pray, plead; cf. oraison).","f":"inexorable, implacable","t":"In-ex-orare = can’t be moved by prayer. Like death or the tide: beg all you want."},{"w":"lambast","p":"v.","m":"To criticise harshly.","e":"1630s, probably <i>lam</i> (to beat, from Old Norse <i>lemja</i>) + <i>baste</i> (to thrash). Both halves mean hitting.","f":"éreinter, fustiger, descendre en flammes","t":"Lam + baste = beat + beat. A critic who lambasts a film gives it a double thrashing: « se faire éreinter par la critique »."},{"w":"mawkish","p":"adj.","m":"Excessively, sickly sentimental.","e":"From <i>mawk</i> (maggot), Old Norse <i>maðkr</i>. In the 1660s it meant “sickly, nauseated”; by the 1700s, “sickly-sweet sentimental”.","f":"mièvre, à l’eau de rose, gnangnan","t":"Sentimentality so sweet it turns your stomach like maggots. A mawkish Christmas ad = mièvre."},{"w":"meticulous","p":"adj.","m":"Showing great attention to detail; very careful.","e":"Latin <i>meticulosus</i> (fearful, timid), from <i>metus</i> (fear). In 19th-century French, <i>méticuleux</i> shifted to “afraid of making mistakes”, hence careful.","f":"méticuleux, minutieux","t":"Same as méticuleux. Metus = fear: a meticulous person is scared of making a single mistake."},{"w":"mitigate","p":"v.","m":"To make less severe or painful.","e":"Latin <i>mitigare</i> (to soften): <i>mitis</i> (mild, gentle) + <i>agere</i> (to make).","f":"atténuer, adoucir, mitiger","t":"Mitigating circumstances = « circonstances atténuantes ». Mitis = soft: you soften the blow."},{"w":"obscure","p":"adj. / v.","m":"Not well known, or unclear; to conceal.","e":"Latin <i>obscurus</i> (dark, dim, hidden).","f":"obscur; obscurcir","t":"Identical to obscur. Something in the dark is either unknown or hard to see clearly."},{"w":"perfidy","p":"n.","m":"Deceitfulness; treachery.","e":"Latin <i>perfidia</i> (faithlessness): <i>per-</i> (away, to ruin) + <i>fides</i> (faith).","f":"perfidie","t":"« La perfide Albion »: the classic French jab at England’s supposed treachery. Per + fides = breaking faith."},{"w":"platitude","p":"n.","m":"A remark used too often to be interesting; a cliché.","e":"French <i>platitude</i> (17th century), “flatness”, from <i>plat</i> (flat), from Vulgar Latin <i>plattus</i>, from Greek <i>platys</i> (broad, flat).","f":"platitude, banalité, lieu commun","t":"Same as « platitude »: a flat, dull remark. “Let’s think outside the box” is a corporate platitude."},{"w":"preclude","p":"v.","m":"To prevent from happening; make impossible.","e":"Latin <i>praecludere</i> (to shut off in advance): <i>prae-</i> (before) + <i>claudere</i> (to close).","f":"empêcher, exclure, écarter","t":"Pre + close = closing the door in advance. Same root as exclude and clore."},{"w":"predilection","p":"n.","m":"A preference or special liking.","e":"French <i>prédilection</i>, from Medieval Latin <i>praedilectio</i>: <i>prae-</i> (before) + <i>diligere</i> (to love, choose).","f":"prédilection","t":"Identical: « un sujet de prédilection ». A predilection for good coffee is a favourite habit."},{"w":"prescience","p":"n.","m":"Knowledge of events before they happen; foresight.","e":"Latin <i>praescientia</i>: <i>prae-</i> (before) + <i>scire</i> (to know).","f":"prescience, clairvoyance","t":"Pre + science = knowing before. A prescient investor saw the crash coming."},{"w":"querulous","p":"adj.","m":"Complaining in a whining, petulant way.","e":"Latin <i>querulus</i>, from <i>queri</i> (to complain). Same root as querelle and quarrel.","f":"plaintif, geignard, ronchon","t":"Queri → querelle. A querulous person picks small complaints all day long."},{"w":"recondite","p":"adj.","m":"Little known; obscure; hard to understand.","e":"Latin <i>reconditus</i> (hidden, put away), from <i>recondere</i>: <i>re-</i> + <i>condere</i> (to put, store). Its cousin <i>abscondere</i> (to hide away) gave French <i>abscons</i>.","f":"abscons, ésotérique, obscur","t":"Recondite ≈ abscons: knowledge stored away where few can find it, like a footnote in a dusty archive."},{"w":"reticent","p":"adj.","m":"Not revealing one’s thoughts readily; reserved.","e":"Latin <i>reticentem</i>, from <i>reticere</i> (to keep silent): <i>re-</i> + <i>tacere</i> (to be silent), as in taciturne.","f":"réservé, discret, taciturne (≠ réticent)","t":"Tacere = se taire: a reticent person holds back their words. Modern French réticent means reluctant; for the GRE, think taciturn.","x":"Faux ami"},{"w":"rustic","p":"adj.","m":"Of the countryside; simple, unsophisticated.","e":"Latin <i>rusticus</i>, from <i>rus</i> (countryside), as in rural.","f":"rustique, campagnard","t":"Same as rustique. Rus = countryside: a rustic table is rough wood from the farm."},{"w":"superfluous","p":"adj.","m":"Unnecessary; more than enough.","e":"Latin <i>superfluus</i> (overflowing): <i>super</i> (over) + <i>fluere</i> (to flow).","f":"superflu","t":"Superflu: water overflowing the glass. The extra words on a slide are superfluous."},{"w":"torpor","p":"n.","m":"Physical or mental inactivity; lethargy.","e":"Latin <i>torpor</i> (numbness), from <i>torpere</i> (to be numb). The Latin <i>torpedo</i> was the electric ray, the fish that numbs its prey.","f":"torpeur, léthargie","t":"« La torpeur de l’après-midi ». Picture being zapped by a torpille fish: numb and sluggish."},{"w":"vociferous","p":"adj.","m":"Loud and forceful in expressing opinions.","e":"Latin <i>vociferari</i> (to shout): <i>vox, vocis</i> (voice) + <i>ferre</i> (to carry).","f":"véhément, bruyant, vociférant","t":"« Vociférer » = to yell. A vociferous critic carries their voice far and loud."},{"w":"volubility","p":"n.","m":"Fluent, ready, continuous speech; talkativeness.","e":"Latin <i>volubilis</i> (that turns, rolls easily), from <i>volvere</i> (to roll).","f":"volubilité, loquacité","t":"Words that keep rolling out (volvere). Same as « volubilité ». Opposite of laconic and reticent."}]},{"name":"Common Words III","slug":"common-words-iii","series":"Common Words","words":[{"w":"abstain","p":"v.","m":"To deliberately refrain from doing or consuming something.","e":"Latin <i>abstinere</i>, “to hold oneself back”: <i>abs-</i> (away) + <i>tenere</i> (to hold). Came through Old French <i>abstenir</i>.","f":"s’abstenir","t":"Same as « s’abstenir » (and l’abstention in a vote). You hold yourself away from the thing."},{"w":"ameliorate","p":"v.","m":"To make something bad better; improve.","e":"From French <i>améliorer</i>, from Latin <i>ad-</i> + <i>melior</i> (better). The 18th-century English form added Latin-looking <i>-ate</i>.","f":"améliorer","t":"Ameliorate = améliorer, word for word. Melior = meilleur."},{"w":"apathy","p":"n.","m":"Lack of interest, enthusiasm or concern.","e":"Greek <i>apatheia</i>: <i>a-</i> (without) + <i>pathos</i> (feeling, suffering). The Stoics prized it as freedom from passion.","f":"apathie, indifférence","t":"A-pathos = no feeling, the opposite of sympathy. Same as « apathie »."},{"w":"ascetic","p":"adj. / n.","m":"Practising strict self-denial; a person who does so.","e":"Greek <i>askētikos</i>, from <i>askētēs</i> (monk, hermit), from <i>askein</i> (to exercise, train). First used of athletes in training, then of hermits training the soul.","f":"ascétique, ascète","t":"Picture a desert hermit training like an athlete, but for the soul: no food, no comfort. « Une vie ascétique »."},{"w":"avaricious","p":"adj.","m":"Extremely greedy for wealth.","e":"Latin <i>avaritia</i> (greed), from <i>avarus</i> (greedy), from <i>avere</i> (to crave).","f":"avare, cupide","t":"Molière’s « L’Avare », Harpagon clutching his cash box. Avaricious = avare, and greedy for more."},{"w":"belligerent","p":"adj.","m":"Hostile and aggressive; eager to fight.","e":"Latin <i>belligerare</i>, “to wage war”: <i>bellum</i> (war) + <i>gerere</i> (to carry on).","f":"belliqueux, agressif (belligérant = at war)","t":"Bellum = war, as in « belliqueux ». A belligerent client is looking for a fight."},{"w":"circumvent","p":"v.","m":"To find a way around an obstacle or rule.","e":"Latin <i>circumvenire</i>, “to come around, surround”: <i>circum</i> (around) + <i>venire</i> (to come).","f":"contourner","t":"Circum + venir = to come around it. « Contourner la règle »."},{"w":"contrive","p":"v.","m":"To plan or bring about cleverly, often artificially.","e":"Old French <i>controver</i> (to invent, find), from Late Latin <i>contropare</i> (to compare). A contrived plot feels artificial.","f":"inventer, combiner, manigancer; contrived = artificiel","t":"Old French controuver = to invent. A contrived ending is invented too obviously: « forcé, artificiel »."},{"w":"delineate","p":"v.","m":"To describe or outline precisely.","e":"Latin <i>delineare</i>, “to sketch out”: <i>de-</i> + <i>linea</i> (line).","f":"décrire, délimiter, tracer","t":"De + linea = drawing the lines of something. A good brief delineates the scope."},{"w":"denote","p":"v.","m":"To indicate; to be the literal meaning of.","e":"Latin <i>denotare</i>, “to mark out”: <i>de-</i> + <i>notare</i> (to mark), from <i>nota</i> (a mark).","f":"dénoter, désigner, signifier","t":"Same as « dénoter ». Denote = the dictionary meaning; connote = the feeling around it."},{"w":"derivative","p":"adj. / n.","m":"Imitative of another’s work; unoriginal. (Also something derived.)","e":"Late Latin <i>derivativus</i>, from <i>derivare</i>, “to draw off a stream”: <i>de-</i> + <i>rivus</i> (stream).","f":"dérivé; peu original","t":"Water drawn off someone else’s stream. On the GRE, a derivative novel copies others."},{"w":"derive","p":"v.","m":"To obtain or trace from a source.","e":"Old French <i>deriver</i>, from Latin <i>derivare</i>: <i>de-</i> (from) + <i>rivus</i> (stream). Channelling water off a river.","f":"tirer de, dériver de","t":"Picture a channel drawing water from a river: you derive pleasure from a source."},{"w":"disaffected","p":"adj.","m":"Dissatisfied and no longer loyal, especially to authority.","e":"<i>dis-</i> (reverse) + <i>affect</i> (to love, from Latin <i>affectare</i>). Literally having lost one’s affection.","f":"désabusé, mécontent, en rupture","t":"Dis + affection: loyalty and love gone. Disaffected voters have given up on the party."},{"w":"eclectic","p":"adj.","m":"Drawing on a wide variety of sources or styles.","e":"Greek <i>eklektikos</i>, “selective”, from <i>eklegein</i>: <i>ek</i> (out) + <i>legein</i> (to pick). Ancient philosophers who picked the best from every school.","f":"éclectique","t":"Ek + legein = picking out the best bits. « Des goûts éclectiques »."},{"w":"elucidate","p":"v.","m":"To make clear; explain.","e":"Late Latin <i>elucidare</i>: <i>e-</i> (out) + <i>lucidus</i> (bright), from <i>lux</i> (light).","f":"élucider, éclaircir","t":"Same as « élucider ». Lux = light: you shine light on the mystery."},{"w":"eminent","p":"adj.","m":"Famous and respected; outstanding.","e":"Latin <i>eminentem</i>, from <i>eminere</i>, “to stand out”: <i>e-</i> + <i>minere</i> (to project). Related to Latin <i>mons</i> (mountain).","f":"éminent","t":"Une éminence = a hill that sticks out. An eminent scientist stands above the crowd. Not imminent (about to happen)."},{"w":"ephemeral","p":"adj.","m":"Lasting a very short time.","e":"Greek <i>ephēmeros</i>, “lasting a day”: <i>epi</i> (on) + <i>hēmera</i> (day). The mayfly (<i>éphémère</i>) lives one day.","f":"éphémère","t":"Same as « éphémère »: the mayfly that lives a single day. Ephemeral fame, ephemeral trends."},{"w":"fallacious","p":"adj.","m":"Based on a mistaken belief; misleading.","e":"Latin <i>fallaciosus</i>, from <i>fallacia</i> (deceit), from <i>fallere</i> (to deceive). Same root as false and fail.","f":"fallacieux","t":"Identical to « fallacieux ». A fallacy is a trick of reasoning."},{"w":"forlorn","p":"adj.","m":"Pitifully sad and abandoned.","e":"Old English <i>forloren</i>, past participle of <i>forlēosan</i> (to lose completely): <i>for-</i> + <i>lēosan</i> (to lose). Germanic, cousin of German <i>verloren</i>.","f":"abandonné, triste, délaissé","t":"For-lorn = for-lost, verloren. A forlorn puppy left at the roadside."},{"w":"frustrate","p":"v.","m":"To prevent a plan from succeeding; to annoy.","e":"Latin <i>frustrari</i> (to disappoint, deceive), from <i>frustra</i> (in vain).","f":"contrecarrer, déjouer; frustrer","t":"Frustra = in vain. On the GRE, “frustrate a plan” = déjouer: make it come to nothing."},{"w":"guileless","p":"adj.","m":"Innocent and without deception.","e":"<i>guile</i> (Old French <i>guile</i>, deceit, probably from Frankish, related to wile) + <i>-less</i>.","f":"candide, sans malice","t":"Guile = ruse. Guileless = sans ruse. A guileless child tells the truth without thinking."},{"w":"haughty","p":"adj.","m":"Arrogantly superior and disdainful.","e":"From <i>haught</i>, Old French <i>haut</i> (high), from Latin <i>altus</i>. The <i>gh</i> was added by analogy with high.","f":"hautain","t":"Haughty = hautain, from haut. Someone looking down on you from high up."},{"w":"heretic","p":"n.","m":"Someone who holds views contrary to accepted belief.","e":"Greek <i>hairetikos</i> (able to choose), from <i>hairesis</i> (a choosing, a sect).","f":"hérétique","t":"Hairesis = a choice. The heretic chose a different belief from the Church. Same as « hérétique »."},{"w":"immutable","p":"adj.","m":"Unchanging; unable to be changed.","e":"Latin <i>immutabilis</i>: <i>in-</i> (not) + <i>mutare</i> (to change), as in mutation.","f":"immuable","t":"No mutation possible. « Les lois immuables de la physique »."},{"w":"incongruous","p":"adj.","m":"Out of place; not in harmony with the surroundings.","e":"Latin <i>incongruus</i>: <i>in-</i> (not) + <i>congruus</i> (agreeing), from <i>congruere</i> (to come together).","f":"incongru, déplacé","t":"Same as « incongru ». Flip-flops at a board meeting."},{"w":"insidious","p":"adj.","m":"Spreading gradually and harmfully, often unnoticed.","e":"Latin <i>insidiosus</i> (cunning), from <i>insidiae</i> (ambush), from <i>insidere</i> (to sit in, lie in wait).","f":"insidieux, sournois","t":"Insidiae = an ambush. An insidious disease lies in wait. Same as « insidieux »."},{"w":"itinerant","p":"adj.","m":"Travelling from place to place.","e":"Late Latin <i>itinerantem</i>, from <i>itinerari</i> (to travel), from <i>iter, itineris</i> (journey).","f":"itinérant, ambulant","t":"Iter = journey, as in itinéraire. Itinerant workers follow the harvest."},{"w":"jingoism","p":"n.","m":"Extreme, aggressive patriotism.","e":"From a British music-hall song of 1878 supporting war against Russia, with the oath “by Jingo” (a euphemism for Jesus). Supporters were mocked as jingoes.","f":"chauvinisme, nationalisme belliqueux","t":"Picture Victorian Londoners singing for war in a music hall. Same idea as French « chauvinisme »."},{"w":"jubilant","p":"adj.","m":"Feeling or expressing great joy.","e":"Latin <i>iubilare</i> (to shout with joy), originally a shepherd’s call; later linked to the Hebrew <i>yobel</i> (jubilee).","f":"jubilant, exultant","t":"« Jubiler » = to rejoice. A jubilant crowd after a final whistle."},{"w":"juxtapose","p":"v.","m":"To place side by side for contrast.","e":"French <i>juxtaposer</i>, from Latin <i>iuxta</i> (beside) + French <i>poser</i> (to place).","f":"juxtaposer","t":"Identical to « juxtaposer ». A before/after slide juxtaposes two images."},{"w":"languid","p":"adj.","m":"Slow and relaxed; lacking energy.","e":"Latin <i>languidus</i> (faint, weak), from <i>languere</i> (to be weak). Same root as languish.","f":"langoureux, alangui, nonchalant","t":"Think « languir » and « langueur »: a languid afternoon in the heat."},{"w":"magnanimous","p":"adj.","m":"Generous and forgiving, especially to a rival.","e":"Latin <i>magnanimus</i>: <i>magnus</i> (great) + <i>animus</i> (soul, spirit).","f":"magnanime","t":"Magna + anima = a great soul. Same as « magnanime ». The winner who praises the loser."},{"w":"mollify","p":"v.","m":"To calm someone’s anger or anxiety.","e":"Latin <i>mollificare</i>: <i>mollis</i> (soft) + <i>facere</i> (to make).","f":"apaiser, amadouer","t":"Mollis = mou. To mollify an angry client = to soften them."},{"w":"negligible","p":"adj.","m":"So small or unimportant it can be ignored.","e":"From French <i>négligeable</i>, from Latin <i>neglegere</i> (to disregard): <i>nec</i> (not) + <i>legere</i> (to pick up).","f":"négligeable","t":"Identical to « négligeable ». Something you can neglect."},{"w":"panache","p":"n.","m":"Flamboyant confidence of style.","e":"French <i>panache</i>, the plume of feathers on a helmet, from Italian <i>pennacchio</i>, from Latin <i>penna</i> (feather).","f":"panache","t":"Cyrano de Bergerac’s last word: « mon panache »! The helmet plume worn with style."},{"w":"precocious","p":"adj.","m":"Having developed abilities unusually early.","e":"Latin <i>praecox</i>, “ripened early”: <i>prae</i> (before) + <i>coquere</i> (to cook, ripen).","f":"précoce","t":"Same as « précoce »: cooked before its time. A precocious child reads at three."},{"w":"quotidian","p":"adj.","m":"Ordinary, everyday.","e":"Latin <i>quotidianus</i>, from <i>quotidie</i> (daily): <i>quot</i> (how many) + <i>dies</i> (day).","f":"quotidien","t":"Quotidian = « quotidien ». Le Quotidien, your daily paper: totally ordinary."},{"w":"refractory","p":"adj.","m":"Stubborn and unmanageable.","e":"Latin <i>refractarius</i> (obstinate), from <i>refringere</i> (to break back): <i>re-</i> + <i>frangere</i> (to break).","f":"réfractaire, rebelle","t":"Les « réfractaires » refused to submit (e.g. to the STO in WWII). Refractory = resists control."},{"w":"rudimentary","p":"adj.","m":"Basic, elementary; undeveloped.","e":"Latin <i>rudimentum</i> (first attempt), from <i>rudis</i> (rough, untrained).","f":"rudimentaire","t":"Identical to « rudimentaire ». Rudis = raw, rough."},{"w":"spurious","p":"adj.","m":"False; not genuine or valid.","e":"Late Latin <i>spurius</i> (illegitimate, of unknown father).","f":"faux, fallacieux, apocryphe","t":"Spurius = illegitimate child: a spurious argument doesn’t come from a real source."},{"w":"staunch","p":"adj.","m":"Very loyal and committed.","e":"Old French <i>estanche</i> (watertight), from <i>estanchier</i> (to stop a flow). Watertight → reliable → loyal.","f":"loyal, fervent, inébranlable","t":"Étanche = watertight! A staunch ally never leaks."},{"w":"subsume","p":"v.","m":"To include within a larger group.","e":"Modern Latin <i>subsumere</i>: <i>sub</i> (under) + <i>sumere</i> (to take).","f":"englober, subsumer","t":"Take under: the smaller category is taken under the bigger one."},{"w":"supplant","p":"v.","m":"To replace, often by force or scheming.","e":"Latin <i>supplantare</i>, “to trip up”: <i>sub</i> (under) + <i>planta</i> (sole of the foot).","f":"supplanter, évincer","t":"Same as « supplanter »: you trip someone up and take their place."},{"w":"tantamount","p":"adj.","m":"Equivalent in seriousness to.","e":"Anglo-French <i>tant amunter</i>, “to amount to as much”: <i>tant</i> (so much) + <i>amonter</i> (to go up, amount).","f":"équivalent à, qui revient à","t":"Tant + monter = amounts to as much. Silence is tantamount to consent."},{"w":"tenacious","p":"adj.","m":"Holding firmly; persistent.","e":"Latin <i>tenax, tenacis</i>, from <i>tenere</i> (to hold).","f":"tenace","t":"Same as « tenace »: a grip that won’t let go."},{"w":"travesty","p":"n.","m":"A false, absurd or distorted version of something.","e":"French <i>travesti</i> (disguised), from Italian <i>travestire</i>: <i>tra-</i> (across) + <i>vestire</i> (to dress).","f":"parodie, simulacre","t":"« Travesti » = dressed up as something else. A travesty of justice is justice in disguise."},{"w":"treacherous","p":"adj.","m":"Guilty of betrayal; also hazardous.","e":"Old French <i>trecherous</i>, from <i>trechier</i> (to cheat, trick).","f":"traître, perfide; dangereux","t":"Think « tricher »: a treacherous friend cheats you; a treacherous road tricks your tyres."},{"w":"unequivocal","p":"adj.","m":"Leaving no doubt; unambiguous.","e":"<i>un-</i> + equivocal, from Late Latin <i>aequivocus</i>: <i>aequus</i> (equal) + <i>vox</i> (voice).","f":"sans équivoque, catégorique","t":"Exactly « sans équivoque »: only one voice speaking."},{"w":"vehement","p":"adj.","m":"Showing strong, forceful feeling.","e":"Latin <i>vehementem</i> (impetuous, violent), possibly from <i>vehere</i> (to carry) + <i>mens</i> (mind): carried away.","f":"véhément","t":"Same as « véhément »: a mind carried away by passion."},{"w":"vilify","p":"v.","m":"To speak or write about in an abusive, disparaging way.","e":"Late Latin <i>vilificare</i>: <i>vilis</i> (cheap, base) + <i>facere</i> (to make).","f":"diffamer, dénigrer, vilipender","t":"Make vile = « vilipender ». The tabloids vilified her."}]},{"name":"Common Words IV","slug":"common-words-iv","series":"Common Words","words":[{"w":"aberrant","p":"adj.","m":"Departing from what is normal or accepted.","e":"Latin <i>aberrantem</i>, from <i>aberrare</i>: <i>ab-</i> (away) + <i>errare</i> (to wander).","f":"aberrant","t":"Same root as aberration: wandering (errer) off the path. Identical to « aberrant »."},{"w":"abstruse","p":"adj.","m":"Difficult to understand; obscure.","e":"Latin <i>abstrusus</i> (hidden), from <i>abstrudere</i>: <i>abs-</i> (away) + <i>trudere</i> (to push). Pushed away out of sight.","f":"abstrus, abscons","t":"Same as « abstrus »: an idea pushed so far away you can’t reach it."},{"w":"acerbic","p":"adj.","m":"Sharp and forthright, especially in criticism.","e":"Latin <i>acerbus</i> (harsh, bitter, sour), related to <i>acer</i> (sharp).","f":"acerbe, caustique","t":"« Un ton acerbe ». Same acer as aigre and vinaigre."},{"w":"adamant","p":"adj.","m":"Refusing to change one’s mind; unshakable.","e":"Greek <i>adamas</i>, “unconquerable”: <i>a-</i> (not) + <i>daman</i> (to tame). A legendary unbreakable stone, later diamond.","f":"inflexible, intransigent","t":"Adamas = the unbreakable stone that gave « diamant ». An adamant person is diamond-hard."},{"w":"admonitory","p":"adj.","m":"Giving or conveying a warning or reprimand.","e":"Latin <i>admonere</i>, “to remind, warn”: <i>ad-</i> + <i>monere</i> (to warn), as in monitor.","f":"d’avertissement, réprobateur","t":"Ad + monere: a monitor warning you. Une admonestation = a reprimand."},{"w":"apocryphal","p":"adj.","m":"Of doubtful authenticity, though widely repeated.","e":"Greek <i>apokryphos</i> (hidden): <i>apo</i> + <i>kryptein</i> (to hide). The Apocrypha were biblical books excluded as of uncertain origin.","f":"apocryphe","t":"Same as « apocryphe ». Like the famous quote nobody actually said."},{"w":"blatant","p":"adj.","m":"Done openly and unashamedly; very obvious.","e":"Coined by Edmund Spenser in <i>The Faerie Queene</i> (1596) for the “Blatant Beast”, a noisy monster of slander; perhaps from Latin <i>blatire</i> (to babble).","f":"flagrant, criant","t":"Spenser’s loud Blatant Beast: blatant things shout at you. « Un mensonge flagrant »."},{"w":"bumbling","p":"adj.","m":"Acting in a confused or clumsy way.","e":"From <i>bumble</i>, an imitative English word (like the buzz of a bumblebee), meaning to blunder or ramble.","f":"maladroit, empoté","t":"A bumblebee bumping into windows. Inspector Clouseau is a bumbling detective."},{"w":"burgeon","p":"v.","m":"To grow or increase rapidly; flourish.","e":"Old French <i>borjoner</i> (to bud), from <i>borjon</i> (bud), modern <i>bourgeon</i>.","f":"bourgeonner, croître rapidement","t":"Burgeon = « bourgeonner »: buds bursting out in spring. A burgeoning start-up scene."},{"w":"confound","p":"v.","m":"To confuse; or to prove wrong.","e":"Old French <i>confondre</i>, from Latin <i>confundere</i>, “to pour together”: <i>com-</i> + <i>fundere</i> (to pour).","f":"confondre, déconcerter","t":"Same as « confondre »: everything poured together. Results that confound the experts prove them wrong."},{"w":"construe","p":"v.","m":"To interpret a meaning.","e":"Latin <i>construere</i>, “to pile together, build”: <i>com-</i> + <i>struere</i> (to build). In grammar, to build up a sentence’s meaning.","f":"interpréter","t":"You construct a meaning. Misconstrue = to build the wrong one."},{"w":"contingent","p":"adj. / n.","m":"Dependent on something uncertain. (n.: a group within a larger one.)","e":"Latin <i>contingentem</i>, from <i>contingere</i>, “to touch, befall”: <i>com-</i> + <i>tangere</i> (to touch).","f":"subordonné à, éventuel; contingent","t":"The offer is contingent on due diligence: it touches on it and depends on it. « Les contingences »."},{"w":"copious","p":"adj.","m":"Abundant, plentiful.","e":"Latin <i>copiosus</i>, from <i>copia</i> (abundance), as in cornucopia.","f":"copieux, abondant","t":"« Un repas copieux ». Copia = abundance."},{"w":"decorum","p":"n.","m":"Behaviour in keeping with good taste and propriety.","e":"Latin <i>decorum</i> (that which is proper), from <i>decere</i> (to be fitting).","f":"décorum, bienséance","t":"Identical to « le décorum ». Same family as decorous."},{"w":"denigrate","p":"v.","m":"To criticise unfairly; belittle.","e":"Latin <i>denigrare</i>, “to blacken”: <i>de-</i> + <i>nigrare</i>, from <i>niger</i> (black).","f":"dénigrer","t":"Same as « dénigrer »: blackening someone’s name."},{"w":"discrete","p":"adj.","m":"Separate and distinct.","e":"Latin <i>discretus</i> (separated), from <i>discernere</i>: <i>dis-</i> (apart) + <i>cernere</i> (to sift). Same origin as discreet, split in spelling later.","f":"distinct, séparé; discret (maths)","t":"Discrete = distinct units, like discrete maths. Discreet (ee) = « discret », tactful."},{"w":"eradicate","p":"v.","m":"To destroy completely; wipe out.","e":"Latin <i>eradicare</i>, “to pull up by the roots”: <i>e-</i> (out) + <i>radix</i> (root).","f":"éradiquer","t":"Radix = racine: pulling the weed out by its root. Same as « éradiquer »."},{"w":"espouse","p":"v.","m":"To adopt or support a cause or belief.","e":"Old French <i>espouser</i> (to marry), from Latin <i>sponsare</i>, from <i>spondere</i> (to promise).","f":"épouser (une cause), embrasser","t":"Exactly « épouser une cause »: you marry the idea."},{"w":"exacting","p":"adj.","m":"Making great demands; strict.","e":"From <i>exact</i> (to demand), Latin <i>exigere</i>, “to drive out, demand”: <i>ex-</i> + <i>agere</i>.","f":"exigeant","t":"Exacting = « exigeant », from the same exigere. An exacting partner."},{"w":"exalt","p":"v.","m":"To praise highly; raise in rank.","e":"Latin <i>exaltare</i>: <i>ex-</i> + <i>altus</i> (high).","f":"exalter, glorifier","t":"Ex + altus = lift up high. « Exalter »."},{"w":"exonerate","p":"v.","m":"To clear from blame.","e":"Latin <i>exonerare</i>, “to unload”: <i>ex-</i> + <i>onus, oneris</i> (burden).","f":"disculper, exonérer","t":"Onus = burden: lifting the burden of guilt off someone. « Exonérer » in French is mostly about taxes, but same image."},{"w":"expound","p":"v.","m":"To explain in detail.","e":"Old French <i>espondre</i>, from Latin <i>exponere</i>, “to put forth”: <i>ex-</i> + <i>ponere</i> (to place).","f":"exposer, expliquer en détail","t":"Expound = « exposer » (same exponere). Expounding a theory at length."},{"w":"forthcoming","p":"adj.","m":"Willing to share information; also about to happen.","e":"English <i>forth</i> (forward) + <i>coming</i>. Germanic.","f":"ouvert, communicatif; à venir","t":"Coming forth with information. An unforthcoming witness says nothing."},{"w":"hackneyed","p":"adj.","m":"Overused, unoriginal; trite.","e":"From <i>hackney</i>, a horse for hire (perhaps from Hackney, the London village). A horse used by everyone became anything worn out.","f":"rebattu, éculé, banal","t":"Picture a tired hired horse ridden by everyone. A hackneyed phrase has been ridden to death."},{"w":"iconoclastic","p":"adj.","m":"Attacking cherished beliefs or institutions.","e":"Greek <i>eikōn</i> (image) + <i>klastēs</i> (breaker). From the Byzantine image-smashers.","f":"iconoclaste","t":"The adjective of iconoclast: smashing sacred images, or sacred ideas."},{"w":"idiosyncrasy","p":"n.","m":"A peculiar habit or way of behaving.","e":"Greek <i>idiosynkrasia</i>: <i>idios</i> (one’s own) + <i>synkrasis</i> (mixture of temperaments).","f":"particularité, manie, idiosyncrasie","t":"Idios = one’s own (as in idiom): your own personal mix of quirks."},{"w":"ignoble","p":"adj.","m":"Dishonourable; base.","e":"Latin <i>ignobilis</i>: <i>in-</i> (not) + <i>nobilis</i> (noble, well known).","f":"ignoble, vil","t":"Not noble. Same as « ignoble »."},{"w":"implacable","p":"adj.","m":"Unable to be appeased; relentless.","e":"Latin <i>implacabilis</i>: <i>in-</i> (not) + <i>placare</i> (to calm, appease).","f":"implacable","t":"Same as « implacable »: impossible to placate."},{"w":"implausible","p":"adj.","m":"Not seeming reasonable or likely.","e":"<i>in-</i> + Latin <i>plausibilis</i> (deserving applause), from <i>plaudere</i> (to clap).","f":"invraisemblable, peu plausible","t":"An excuse nobody would applaud. « Pas plausible »."},{"w":"incorrigible","p":"adj.","m":"Not able to be corrected or reformed.","e":"Latin <i>incorrigibilis</i>: <i>in-</i> + <i>corrigere</i> (to correct).","f":"incorrigible","t":"Identical to « incorrigible »: beyond correction."},{"w":"indifference","p":"n.","m":"Lack of interest or concern. (Also mediocrity.)","e":"Latin <i>indifferentia</i>: <i>in-</i> + <i>differre</i> (to differ). It makes no difference to you.","f":"indifférence","t":"Same as « indifférence ». Careful: indifferent can also mean mediocre on the GRE."},{"w":"ingratiate","p":"v.","m":"To bring oneself into favour, often by flattery.","e":"Italian <i>ingratiare</i>, from Latin <i>in gratiam</i> (into favour), <i>gratia</i> (grace).","f":"s’attirer les bonnes grâces de, s’insinuer","t":"Getting into someone’s good graces (gratia). « S’attirer les bonnes grâces »."},{"w":"intransigent","p":"adj.","m":"Unwilling to compromise.","e":"Spanish <i>intransigente</i>, from Latin <i>in-</i> + <i>transigere</i> (to come to an agreement).","f":"intransigeant","t":"Same as « intransigeant »: no transaction possible."},{"w":"largess","p":"n.","m":"Generosity in giving gifts or money.","e":"Old French <i>largesse</i>, from <i>large</i> (generous), Latin <i>largus</i> (abundant).","f":"largesse, générosité","t":"Identical to « largesse ». A lord throwing coins from his carriage."},{"w":"laudable","p":"adj.","m":"Deserving praise.","e":"Latin <i>laudabilis</i>, from <i>laudare</i> (to praise), <i>laus</i> (praise).","f":"louable","t":"Laud = louer (to praise). Laudable = louable."},{"w":"myopic","p":"adj.","m":"Short-sighted; lacking foresight.","e":"Greek <i>myōps</i>, “short-sighted”: <i>myein</i> (to shut) + <i>ōps</i> (eye). Squinting with half-closed eyes.","f":"myope; à courte vue","t":"Same as « myope ». A myopic strategy only sees this quarter."},{"w":"opaque","p":"adj.","m":"Not transparent; hard to understand.","e":"Latin <i>opacus</i> (shaded, dark).","f":"opaque, obscur","t":"Same as « opaque »: light can’t get through, and neither can meaning."},{"w":"ostentatious","p":"adj.","m":"Designed to impress; showy.","e":"Latin <i>ostentatio</i> (display), from <i>ostendere</i> (to show): <i>ob-</i> + <i>tendere</i> (to stretch).","f":"ostentatoire, tape-à-l’œil","t":"« Ostentatoire »: stretching it out for everyone to see."},{"w":"pedantic","p":"adj.","m":"Overly concerned with minor details and rules.","e":"Italian <i>pedante</i> (schoolmaster), probably related to Greek <i>paideuein</i> (to teach).","f":"pédant, pointilleux","t":"Same as « pédant »: the schoolmaster correcting your commas."},{"w":"petulant","p":"adj.","m":"Childishly sulky or bad-tempered.","e":"Latin <i>petulantem</i> (forward, insolent), from <i>petere</i> (to attack, seek).","f":"irritable, boudeur (≠ pétulant)","x":"Faux ami","t":"Careful: French « pétulant » means lively. English petulant = a sulking toddler."},{"w":"pragmatic","p":"adj.","m":"Dealing with things practically, not theoretically.","e":"Greek <i>pragmatikos</i> (businesslike), from <i>pragma</i> (deed, affair), from <i>prassein</i> (to do).","f":"pragmatique","t":"Pragma = action. Same as « pragmatique »."},{"w":"provincial","p":"adj.","m":"Unsophisticated, narrow-minded.","e":"Latin <i>provincialis</i>, from <i>provincia</i> (a territory outside Rome).","f":"provincial, borné","t":"Like parochial: thinking from far away from the capital. « Un esprit provincial »."},{"w":"pundit","p":"n.","m":"An expert who gives opinions publicly.","e":"Hindi <i>paṇḍit</i>, from Sanskrit <i>paṇḍita</i> (learned man).","f":"expert, commentateur","t":"A pandit was a learned Hindu scholar. Today’s pundits are TV experts."},{"w":"reconcile","p":"v.","m":"To restore friendly relations; make compatible.","e":"Latin <i>reconciliare</i>: <i>re-</i> + <i>conciliare</i> (to bring together).","f":"réconcilier, concilier","t":"Same as « réconcilier ». You also reconcile two sets of numbers in a model."},{"w":"refute","p":"v.","m":"To prove wrong.","e":"Latin <i>refutare</i> (to drive back, disprove).","f":"réfuter","t":"Same as « réfuter ». Not just deny: prove false."},{"w":"soporific","p":"adj.","m":"Causing sleep; very boring.","e":"Latin <i>sopor</i> (deep sleep) + <i>-ficus</i> (making).","f":"soporifique","t":"Identical to « soporifique ». A soporific lecture."},{"w":"temperance","p":"n.","m":"Moderation, self-restraint (especially with alcohol).","e":"Latin <i>temperantia</i> (moderation), from <i>temperare</i> (to mix in due proportion).","f":"tempérance, modération","t":"One of the four cardinal virtues: « la tempérance ». Tempered = mixed in the right dose."},{"w":"tortuous","p":"adj.","m":"Full of twists and turns; overly complex.","e":"Latin <i>tortuosus</i>, from <i>tortus</i> (twisted), from <i>torquere</i> (to twist).","f":"tortueux","t":"Same as « tortueux ». Not torturous (painful) — tortuous twists."},{"w":"underscore","p":"v.","m":"To emphasise.","e":"English <i>under</i> + <i>score</i> (a line, from Old Norse <i>skor</i>, notch). Literally to underline.","f":"souligner","t":"Underline = « souligner ». The data underscores the risk."},{"w":"unscrupulous","p":"adj.","m":"Having no moral principles; not honest.","e":"<i>un-</i> + scrupulous, from Latin <i>scrupulus</i> (a small sharp stone): the pebble in your sandal that bothers your conscience.","f":"sans scrupules","t":"Scrupulus = a little stone in your shoe. The unscrupulous feel no pebble at all. « Sans scrupules »."}]},{"name":"Common Words V","slug":"common-words-v","series":"Common Words","words":[{"w":"accolade","p":"n.","m":"An award or expression of praise.","e":"French <i>accolade</i>, an embrace, from Latin <i>ad</i> + <i>collum</i> (neck). The knight’s ceremony included an embrace or a tap on the neck with the sword.","f":"distinction, éloge (accolade = hug)","t":"The king dubbing a knight with an embrace around the neck (collum). Today: an honour, a prize."},{"w":"admonish","p":"v.","m":"To warn or reprimand firmly.","e":"Old French <i>amonester</i>, from Latin <i>admonere</i>: <i>ad-</i> + <i>monere</i> (to warn).","f":"admonester, réprimander","t":"Same as « admonester ». Monere = warn, like a monitor."},{"w":"antithetical","p":"adj.","m":"Directly opposed.","e":"Greek <i>antithesis</i>: <i>anti</i> (against) + <i>tithenai</i> (to place). Placed against.","f":"antithétique, opposé","t":"Thesis vs antithesis: placed against each other. « Aux antipodes »."},{"w":"arbitrary","p":"adj.","m":"Based on random choice or personal whim, not reason.","e":"Latin <i>arbitrarius</i>, from <i>arbiter</i> (judge). Left to the judge’s discretion.","f":"arbitraire","t":"Same as « arbitraire »: whatever the arbitre decides on a whim."},{"w":"arcane","p":"adj.","m":"Understood by few; mysterious.","e":"Latin <i>arcanus</i> (secret), from <i>arca</i> (chest, box). Locked in a box.","f":"obscur, ésotérique; les arcanes","t":"« Les arcanes du pouvoir »: secrets locked in a chest (arca)."},{"w":"audacity","p":"n.","m":"Willingness to take bold risks; rude boldness.","e":"Latin <i>audacia</i>, from <i>audax</i> (bold), <i>audere</i> (to dare).","f":"audace; culot","t":"« L’audace ». Can be praise (bold) or blame (the audacity to ask!)."},{"w":"austere","p":"adj.","m":"Severe or strict; plain, without comfort.","e":"Greek <i>austēros</i> (harsh, bitter, making the tongue dry), via Latin <i>austerus</i>.","f":"austère","t":"Same as « austère ». A monk’s cell: bare walls, no comfort."},{"w":"brazen","p":"adj.","m":"Bold and shameless.","e":"Old English <i>bræsen</i> (made of brass). Brass = hard and loud, hence shameless.","f":"effronté, éhonté","t":"A face made of brass: no blush possible. A brazen lie."},{"w":"circumscribe","p":"v.","m":"To restrict within limits.","e":"Latin <i>circumscribere</i>: <i>circum</i> (around) + <i>scribere</i> (to write, draw). Drawing a line around.","f":"circonscrire, limiter","t":"Same as « circonscrire »: drawing a circle around something (une circonscription)."},{"w":"constituent","p":"n. / adj.","m":"A component part; a voter in a district.","e":"Latin <i>constituentem</i>, from <i>constituere</i> (to set up): <i>com-</i> + <i>statuere</i> (to set).","f":"composant, constituant; électeur","t":"The parts that constitute something, or the voters who constitute a constituency."},{"w":"dilettante","p":"n.","m":"A person with superficial interest in an art or subject.","e":"Italian <i>dilettante</i> (lover of the arts), from <i>dilettare</i> (to delight), Latin <i>delectare</i>.","f":"dilettante, amateur","t":"Same as « dilettante »: dabbling for delight, never mastering."},{"w":"foment","p":"v.","m":"To stir up trouble or rebellion.","e":"Latin <i>fomentare</i>, from <i>fomentum</i> (a warm poultice), from <i>fovere</i> (to warm).","f":"fomenter","t":"Same as « fomenter un complot »: keeping a revolt warm until it hatches."},{"w":"garrulous","p":"adj.","m":"Excessively talkative about trivial things.","e":"Latin <i>garrulus</i> (chattering), from <i>garrire</i> (to chatter).","f":"bavard, loquace","t":"Garrire = to chatter like a bird. A garrulous seatmate on a long flight."},{"w":"gauche","p":"adj.","m":"Socially awkward; tactless.","e":"French <i>gauche</i> (left; clumsy), probably from Frankish <i>welkan</i> (to wilt).","f":"gauche, maladroit","t":"Exactly French « gauche »: clumsy, like doing everything with the left hand."},{"w":"haphazard","p":"adj.","m":"Lacking order or plan; random.","e":"English <i>hap</i> (luck, from Old Norse <i>happ</i>) + <i>hazard</i> (chance, via French <i>hasard</i> from Arabic <i>az-zahr</i>, the die).","f":"au hasard, désordonné","t":"Hap + hasard = luck + luck. Nothing planned."},{"w":"hegemony","p":"n.","m":"Dominance of one group or state over others.","e":"Greek <i>hēgemonia</i> (leadership), from <i>hēgemōn</i> (leader), <i>hēgeisthai</i> (to lead).","f":"hégémonie","t":"Same as « hégémonie »: Athens leading the other Greek cities."},{"w":"inimical","p":"adj.","m":"Hostile; harmful.","e":"Late Latin <i>inimicalis</i>, from <i>inimicus</i> (enemy): <i>in-</i> + <i>amicus</i> (friend).","f":"hostile, nuisible","t":"In-amicus = not a friend → « ennemi ». Conditions inimical to growth."},{"w":"inscrutable","p":"adj.","m":"Impossible to understand or interpret.","e":"Late Latin <i>inscrutabilis</i>: <i>in-</i> + <i>scrutari</i> (to search, examine).","f":"impénétrable, insondable","t":"Can’t be scrutinised. An inscrutable poker face."},{"w":"insolent","p":"adj.","m":"Rude and disrespectful.","e":"Latin <i>insolentem</i> (unusual, arrogant): <i>in-</i> + <i>solere</i> (to be accustomed).","f":"insolent","t":"Same as « insolent »."},{"w":"intrepid","p":"adj.","m":"Fearless; adventurous.","e":"Latin <i>intrepidus</i>: <i>in-</i> (not) + <i>trepidus</i> (alarmed).","f":"intrépide","t":"Same as « intrépide »: no trépidation."},{"w":"inveterate","p":"adj.","m":"Having a long-established habit unlikely to change.","e":"Latin <i>inveteratus</i> (grown old), from <i>vetus</i> (old), as in veteran.","f":"invétéré","t":"Same as « un fumeur invétéré ». A veteran habit."},{"w":"irrevocable","p":"adj.","m":"Not able to be changed or reversed.","e":"Latin <i>irrevocabilis</i>: <i>in-</i> + <i>revocare</i> (to call back).","f":"irrévocable","t":"Same as « irrévocable »: can’t be called back."},{"w":"lionize","p":"v.","m":"To treat someone as a celebrity.","e":"From lion, in the 18th-century sense “a celebrity”: from the custom of taking visitors to see the lions at the Tower of London.","f":"porter aux nues, aduler","t":"Treat someone like the star attraction: the lion everyone queues to see."},{"w":"munificent","p":"adj.","m":"Very generous.","e":"Latin <i>munificus</i>: <i>munus</i> (gift, duty) + <i>facere</i> (to make).","f":"munificent, généreux","t":"A maker of gifts. Same as « munificent » (rare in French)."},{"w":"myriad","p":"n. / adj.","m":"Countless; a great number.","e":"Greek <i>myrias</i> (ten thousand), from <i>myrioi</i> (countless).","f":"myriade","t":"« Une myriade d’étoiles ». Literally 10,000."},{"w":"obsequious","p":"adj.","m":"Excessively eager to please or obey.","e":"Latin <i>obsequiosus</i>, from <i>obsequi</i> (to comply): <i>ob-</i> + <i>sequi</i> (to follow).","f":"obséquieux","t":"Same as « obséquieux »: following someone everywhere to please them."},{"w":"ostracize","p":"v.","m":"To exclude from a group.","e":"Greek <i>ostrakizein</i>, from <i>ostrakon</i> (pottery shard). Athenians voted to exile someone by writing his name on shards.","f":"ostraciser, exclure","t":"Picture Athenians scratching a name on a broken pot to banish him."},{"w":"pedestrian","p":"adj.","m":"Dull, unimaginative.","e":"Latin <i>pedester</i> (on foot; prosaic), from <i>pes, pedis</i> (foot). Prose was “on foot”, poetry had wings.","f":"terne, prosaïque, banal","x":"2nd meaning","t":"Not the person crossing the road: a style that plods on foot instead of flying."},{"w":"pernicious","p":"adj.","m":"Having a harmful effect, especially gradually.","e":"Latin <i>perniciosus</i>, from <i>pernicies</i> (destruction): <i>per-</i> + <i>nex, necis</i> (death).","f":"pernicieux","t":"Same as « pernicieux ». Nex = death, slowly."},{"w":"poignant","p":"adj.","m":"Evoking a keen sense of sadness.","e":"Old French <i>poignant</i> (pricking), from <i>poindre</i>, Latin <i>pungere</i> (to prick).","f":"poignant, émouvant","t":"Same as « poignant »: it pricks your heart (pungere, as in punctuation)."},{"w":"precipitous","p":"adj.","m":"Dangerously steep; also sudden.","e":"Latin <i>praeceps</i> (headlong): <i>prae</i> (before) + <i>caput</i> (head).","f":"abrupt, escarpé; précipité","t":"Head first over the précipice. A precipitous drop in sales."},{"w":"prodigious","p":"adj.","m":"Remarkably great in size or degree.","e":"Latin <i>prodigiosus</i>, from <i>prodigium</i> (omen, marvel).","f":"prodigieux","t":"Same as « prodigieux »: like an omen, it amazes."},{"w":"prolific","p":"adj.","m":"Producing much; productive.","e":"French <i>prolifique</i>, from Latin <i>proles</i> (offspring) + <i>facere</i>.","f":"prolifique","t":"Same as « prolifique »: lots of offspring."},{"w":"propitious","p":"adj.","m":"Favourable; indicating a good chance of success.","e":"Latin <i>propitius</i> (favourable, gracious), perhaps from <i>pro</i> + <i>petere</i> (to seek).","f":"propice","t":"Propitious = « propice »: « un moment propice »."},{"w":"ravenous","p":"adj.","m":"Extremely hungry.","e":"Old French <i>ravineus</i> (violent, rapacious), from <i>raviner</i> (to ravage), Latin <i>rapina</i> (plunder).","f":"affamé, vorace","t":"Hungry enough to plunder (rapina, as in « rapine »). Not from the bird raven."},{"w":"repudiate","p":"v.","m":"To refuse to accept; reject.","e":"Latin <i>repudiare</i> (to divorce, reject), from <i>repudium</i> (divorce).","f":"répudier, rejeter","t":"« Répudier sa femme »: in Rome, a formal divorce. Repudiate a claim = cast it off."},{"w":"rescind","p":"v.","m":"To revoke or cancel.","e":"Latin <i>rescindere</i> (to cut off): <i>re-</i> + <i>scindere</i> (to split).","f":"annuler, révoquer, rescinder","t":"Scindere = scinder, to cut: rescinding a contract cuts it off."},{"w":"resurgent","p":"adj.","m":"Increasing or reviving after a period of decline.","e":"Latin <i>resurgere</i> (to rise again): <i>re-</i> + <i>surgere</i> (to rise).","f":"renaissant, en plein renouveau","t":"Rising again, like resurrection. « Une résurgence »."},{"w":"reverent","p":"adj.","m":"Feeling or showing deep respect.","e":"Latin <i>reverentem</i>, from <i>revereri</i> (to stand in awe of).","f":"révérencieux, respectueux","t":"« Faire la révérence »: a deep, respectful bow."},{"w":"sanction","p":"n. / v.","m":"Official approval OR a penalty (contranym).","e":"Latin <i>sanctio</i> (decree, penalty), from <i>sancire</i> (to make sacred, decree).","f":"approbation; sanction","x":"2nd meaning","t":"A decree can approve or punish. On the GRE it often means approve: « entériner »."},{"w":"scrupulous","p":"adj.","m":"Very careful, honest and thorough.","e":"Latin <i>scrupulosus</i>, from <i>scrupulus</i> (small sharp stone; a pang of conscience).","f":"scrupuleux","t":"Same as « scrupuleux »: feeling every tiny pebble in your shoe."},{"w":"sporadic","p":"adj.","m":"Occurring at irregular intervals.","e":"Greek <i>sporadikos</i> (scattered), from <i>speirein</i> (to sow).","f":"sporadique","t":"Seeds scattered when sowing (as in spore). « Sporadique »."},{"w":"subversive","p":"adj.","m":"Seeking to undermine an established system.","e":"Latin <i>subvertere</i>: <i>sub</i> (under) + <i>vertere</i> (to turn). Turning upside down from below.","f":"subversif","t":"Same as « subversif »: turning the system over from underneath."},{"w":"sycophant","p":"n.","m":"A servile flatterer.","e":"Greek <i>sykophantēs</i> (informer), literally “fig-shower”: <i>sykon</i> (fig) + <i>phainein</i> (to show). Origin of the image debated.","f":"flagorneur, lèche-bottes","t":"The fig-shower: picture a courtier offering figs to the king, nodding at every word."},{"w":"taciturn","p":"adj.","m":"Saying little; reserved.","e":"Latin <i>taciturnus</i>, from <i>tacitus</i> (silent), <i>tacere</i> (to be silent).","f":"taciturne","t":"Same as « taciturne ». Tacere = se taire."},{"w":"tempered","p":"adj.","m":"Moderated or toned down.","e":"Latin <i>temperare</i> (to mix in proper proportion).","f":"tempéré, nuancé, modéré","t":"Like tempered steel or a « climat tempéré »: optimism tempered by realism."},{"w":"tractable","p":"adj.","m":"Easy to control or deal with.","e":"Latin <i>tractabilis</i>, from <i>tractare</i> (to handle), frequentative of <i>trahere</i> (to pull).","f":"docile, maniable","t":"Easy to pull, like a tractor pulling a docile cart. Opposite: intractable."},{"w":"trite","p":"adj.","m":"Overused and unoriginal.","e":"Latin <i>tritus</i> (worn out), from <i>terere</i> (to rub).","f":"banal, rebattu","t":"Rubbed so much it’s worn out. A trite cliché."},{"w":"vacillate","p":"v.","m":"To waver between opinions.","e":"Latin <i>vacillare</i> (to sway, totter).","f":"vaciller, hésiter","t":"Same as « vaciller »: a candle flame swaying back and forth."},{"w":"winsome","p":"adj.","m":"Charming, engaging.","e":"Old English <i>wynsum</i>: <i>wynn</i> (joy) + <i>-sum</i> (-some). Germanic.","f":"charmant, avenant","t":"Win + some: a smile that wins you over. Old English wynn = joy."}]},{"name":"Common Words VI","slug":"common-words-vi","series":"Common Words","words":[{"w":"anomaly","p":"n.","m":"Something that deviates from what is expected.","e":"Greek <i>anōmalia</i>: <i>an-</i> (not) + <i>homalos</i> (even).","f":"anomalie","t":"Same as « anomalie »: the point off the even line."},{"w":"antipathy","p":"n.","m":"A deep-seated dislike.","e":"Greek <i>antipatheia</i>: <i>anti</i> (against) + <i>pathos</i> (feeling).","f":"antipathie","t":"Feeling against: the opposite of sympathy. « Antipathie »."},{"w":"appease","p":"v.","m":"To pacify by giving in to demands.","e":"Old French <i>apaisier</i>: <i>a</i> + <i>pais</i> (peace), Latin <i>pax</i>.","f":"apaiser","t":"Appease = « apaiser »: bringing peace. Munich 1938 = appeasement."},{"w":"arduous","p":"adj.","m":"Involving great effort; difficult.","e":"Latin <i>arduus</i> (steep, difficult).","f":"ardu, pénible","t":"Same as « ardu »: a steep climb."},{"w":"askance","p":"adv.","m":"With suspicion or disapproval (to look askance).","e":"Origin uncertain, 1500s; perhaps from Italian <i>a scancio</i> (sideways).","f":"de travers, avec méfiance","t":"Looking at someone sideways: « regarder de travers »."},{"w":"banality","p":"n.","m":"The quality of being trite or unoriginal.","e":"French <i>banalité</i>, from <i>banal</i>, from the feudal <i>ban</i> (Frankish): the lord’s oven used by all.","f":"banalité","t":"Same as « banalité ». The village four banal again."},{"w":"bolster","p":"v.","m":"To support or strengthen.","e":"Old English <i>bolster</i> (a long pillow). Germanic. To prop up with a cushion.","f":"renforcer, étayer, soutenir","t":"A bolster is a long pillow propping you up. Data that bolsters your case."},{"w":"capricious","p":"adj.","m":"Given to sudden, unpredictable changes.","e":"French <i>capricieux</i>, from Italian <i>capriccio</i> (a sudden start, whim), perhaps from <i>capra</i> (goat) for its leaps.","f":"capricieux","t":"A goat leaping unpredictably: « capricieux »."},{"w":"contrition","p":"n.","m":"Sincere remorse.","e":"Latin <i>contritio</i> (grinding), from <i>conterere</i> (to grind, crush). A heart crushed by guilt.","f":"contrition, repentir","t":"Same as « contrition » in confession: a heart ground down by guilt."},{"w":"craven","p":"adj.","m":"Contemptibly cowardly.","e":"Middle English <i>cravant</i> (defeated), probably from Old French <i>cravanté</i> (crushed).","f":"lâche, couard","t":"Defeated and crushed: a craven surrender."},{"w":"deleterious","p":"adj.","m":"Causing harm.","e":"Greek <i>dēlētērios</i> (noxious), from <i>dēleisthai</i> (to hurt).","f":"délétère, nuisible","t":"Same as « délétère »: « une ambiance délétère »."},{"w":"dilatory","p":"adj.","m":"Slow; tending to delay.","e":"Latin <i>dilatorius</i>, from <i>differre</i> (to delay), supine <i>dilatum</i>.","f":"dilatoire, lent","t":"« Des manœuvres dilatoires »: stalling tactics."},{"w":"dispassionate","p":"adj.","m":"Not influenced by strong emotion; impartial.","e":"<i>dis-</i> + passionate, from Latin <i>passio</i> (suffering).","f":"impartial, objectif, posé","t":"Without passion: a dispassionate analysis."},{"w":"disseminate","p":"v.","m":"To spread widely.","e":"Latin <i>disseminare</i>: <i>dis-</i> (apart) + <i>seminare</i> (to sow), from <i>semen</i> (seed).","f":"disséminer, diffuser","t":"Sowing seeds everywhere: « disséminer »."},{"w":"duress","p":"n.","m":"Threats or pressure used to force someone.","e":"Old French <i>duresse</i> (hardness, harshness), from Latin <i>durus</i> (hard).","f":"contrainte","t":"From dur: signed under duress = sous la contrainte."},{"w":"economical","p":"adj.","m":"Using no more than necessary; thrifty (also: economical with the truth).","e":"Greek <i>oikonomia</i>: <i>oikos</i> (house) + <i>nomos</i> (management).","f":"économe, sobre","t":"House management. On the GRE: economical prose = no wasted words."},{"w":"edifying","p":"adj.","m":"Morally or intellectually instructive.","e":"Latin <i>aedificare</i> (to build): <i>aedes</i> (building) + <i>facere</i>. Building up the soul.","f":"édifiant","t":"Same as « édifiant »: building (édifice) your character."},{"w":"efficacious","p":"adj.","m":"Effective, producing the desired result.","e":"Latin <i>efficax</i>, from <i>efficere</i> (to accomplish).","f":"efficace","t":"Efficacious = « efficace ». Used of remedies."},{"w":"elicit","p":"v.","m":"To draw out a response or fact.","e":"Latin <i>elicere</i>: <i>e-</i> (out) + <i>lacere</i> (to lure).","f":"susciter, obtenir","t":"Lure out a reaction. Not illicit (illegal)."},{"w":"erudite","p":"adj.","m":"Very learned.","e":"Latin <i>eruditus</i>, from <i>erudire</i> (to instruct): <i>e-</i> + <i>rudis</i> (rough). Taking the roughness out.","f":"érudit","t":"Same as « érudit »: no longer rude/rough."},{"w":"esoteric","p":"adj.","m":"Understood by only a small group.","e":"Greek <i>esōterikos</i> (inner), from <i>esō</i> (within). Teachings for inner disciples only.","f":"ésotérique","t":"Same as « ésotérique »: for the inner circle."},{"w":"fastidious","p":"adj.","m":"Very attentive to detail; hard to please.","e":"Latin <i>fastidiosus</i> (disdainful), from <i>fastidium</i> (loathing).","f":"méticuleux, pointilleux (≠ fastidieux)","x":"Faux ami","t":"Careful: « fastidieux » = tedious. Fastidious = maniaque, fussy."},{"w":"flux","p":"n.","m":"Continuous change.","e":"Latin <i>fluxus</i> (flow), from <i>fluere</i> (to flow).","f":"flux, mouvance","t":"Heraclitus: everything flows. A market in flux."},{"w":"furtive","p":"adj.","m":"Secretive; trying not to be noticed.","e":"Latin <i>furtivus</i>, from <i>furtum</i> (theft), <i>fur</i> (thief).","f":"furtif","t":"Same as « furtif »: moving like a thief."},{"w":"harried","p":"adj.","m":"Harassed, stressed by demands.","e":"Old English <i>hergian</i> (to ravage, raid), related to <i>here</i> (army). Germanic.","f":"harcelé, débordé","t":"Raided by an army of emails. A harried consultant on a Sunday."},{"w":"ignominious","p":"adj.","m":"Deserving or causing public disgrace.","e":"Latin <i>ignominia</i>: <i>in-</i> (not) + <i>nomen</i> (name). Loss of one’s good name.","f":"ignominieux, honteux","t":"Same as « ignominieux »: losing your name."},{"w":"impartial","p":"adj.","m":"Treating all equally; fair.","e":"<i>in-</i> + partial, from Latin <i>pars</i> (part). Not taking a part.","f":"impartial","t":"Same as « impartial »."},{"w":"imprudent","p":"adj.","m":"Not showing care for the consequences.","e":"Latin <i>imprudens</i>: <i>in-</i> + <i>prudens</i> (foreseeing), contraction of <i>providens</i>.","f":"imprudent","t":"Same as « imprudent »: not foreseeing."},{"w":"indecorous","p":"adj.","m":"Improper; in bad taste.","e":"Latin <i>indecorus</i>: <i>in-</i> + <i>decorus</i> (fitting).","f":"inconvenant","t":"Breaking « le décorum »."},{"w":"jovial","p":"adj.","m":"Cheerful and friendly.","e":"Latin <i>Iovialis</i> (of Jupiter). Astrologers held those born under Jupiter to be happy.","f":"jovial","t":"Same as « jovial »: born under jolly Jupiter (Jove)."},{"w":"maladroit","p":"adj.","m":"Clumsy, inept.","e":"French <i>maladroit</i>: <i>mal</i> (badly) + <i>adroit</i> (skilful, à droit).","f":"maladroit","t":"Straight from French « maladroit »."},{"w":"maverick","p":"n.","m":"An independent-minded nonconformist.","e":"From Samuel Maverick (1803–1870), a Texas rancher who refused to brand his cattle; unbranded calves were called mavericks.","f":"franc-tireur, non-conformiste","t":"The unbranded calf wandering free from the herd. Also Top Gun’s pilot."},{"w":"mendacity","p":"n.","m":"Untruthfulness, lying.","e":"Latin <i>mendax</i> (lying), from <i>mendum</i> (fault).","f":"mensonge, fausseté","t":"Mendacity sounds like « mensonge », and that’s exactly what it is: a habit of lying."},{"w":"misconstrue","p":"v.","m":"To interpret wrongly.","e":"<i>mis-</i> + construe, Latin <i>construere</i> (to build).","f":"mal interpréter","t":"Building the wrong meaning. Contrast with construe."},{"w":"mundane","p":"adj.","m":"Ordinary, dull; earthly.","e":"Latin <i>mundanus</i>, from <i>mundus</i> (world).","f":"banal, terre-à-terre (≠ mondain)","x":"Faux ami","t":"Careful: « mondain » = society/high life. Mundane = ordinary everyday stuff."},{"w":"nonplussed","p":"adj.","m":"So surprised one doesn’t know how to react.","e":"Latin <i>non plus</i> (no more): a state where nothing more can be said.","f":"perplexe, décontenancé","t":"« Non plus »: you have nothing more to say. Means baffled, not calm."},{"w":"nuance","p":"n.","m":"A subtle difference in meaning or expression.","e":"French <i>nuance</i> (shade), from <i>nuer</i> (to shade), from <i>nue</i> (cloud).","f":"nuance","t":"Straight from French: shades like those of a cloud (nue)."},{"w":"opulence","p":"n.","m":"Great wealth or luxury.","e":"Latin <i>opulentia</i>, from <i>opes</i> (wealth).","f":"opulence","t":"Same as « opulence ». Versailles’ Hall of Mirrors."},{"w":"pejorative","p":"adj.","m":"Expressing contempt or disapproval.","e":"Latin <i>peiorare</i> (to make worse), from <i>peior</i> (worse).","f":"péjoratif","t":"Same as « péjoratif »: making it sound worse."},{"w":"placate","p":"v.","m":"To calm or soothe someone angry.","e":"Latin <i>placare</i> (to calm).","f":"apaiser, calmer","t":"Placare: same root as implacable and plaire. Placate an angry client."},{"w":"polemic","p":"n.","m":"A strong verbal or written attack.","e":"Greek <i>polemikos</i> (warlike), from <i>polemos</i> (war).","f":"polémique","t":"Same as « polémique »: war (polemos) by words."},{"w":"posit","p":"v.","m":"To put forward as fact or a basis for argument.","e":"Latin <i>positus</i>, from <i>ponere</i> (to place).","f":"postuler, poser comme principe","t":"To posit = « poser » a hypothesis on the table."},{"w":"rebuke","p":"v. / n.","m":"To express sharp disapproval.","e":"Anglo-French <i>rebuker</i> (to beat back), from Old French <i>bukier</i> (to strike).","f":"réprimander, reproche","t":"Beat back verbally: a sharp rebuke from the partner."},{"w":"reproach","p":"v. / n.","m":"To express disappointment or disapproval.","e":"Old French <i>reprochier</i>, from Vulgar Latin <i>repropiare</i> (to bring back near).","f":"reprocher, reproche","t":"Same as « reprocher ». Beyond reproach = irréprochable."},{"w":"specious","p":"adj.","m":"Superficially plausible but actually wrong.","e":"Latin <i>speciosus</i> (good-looking), from <i>species</i> (appearance).","f":"spécieux","t":"Same as « spécieux »: pretty on the surface, false inside."},{"w":"stringent","p":"adj.","m":"Strict, precise and exacting.","e":"Latin <i>stringentem</i>, from <i>stringere</i> (to draw tight).","f":"rigoureux, strict","t":"Pulled tight (stringere, as in stricte). Stringent regulations."},{"w":"sullen","p":"adj.","m":"Bad-tempered and sulky.","e":"Anglo-French <i>solein</i> (solitary), from Latin <i>solus</i> (alone).","f":"maussade, renfrogné","t":"Solus = alone: the sulky teen alone in his room."},{"w":"timorous","p":"adj.","m":"Showing fear; timid.","e":"Medieval Latin <i>timorosus</i>, from <i>timor</i> (fear).","f":"craintif, timoré","t":"Same as « timoré ». Timor = fear."},{"w":"transient","p":"adj.","m":"Lasting only a short time.","e":"Latin <i>transire</i> (to go across): <i>trans</i> + <i>ire</i> (to go).","f":"transitoire, passager","t":"Passing through: « transitoire »."},{"w":"truncate","p":"v.","m":"To shorten by cutting off.","e":"Latin <i>truncare</i> (to cut off), from <i>truncus</i> (trunk, maimed).","f":"tronquer","t":"Same as « tronquer »: cut down to the trunk."}]},{"name":"Common Words VII","slug":"common-words-vii","series":"Common Words","words":[{"w":"abate","p":"v.","m":"To become less intense; diminish.","e":"Old French <i>abatre</i> (to beat down), from Latin <i>ad</i> + <i>battuere</i> (to beat).","f":"diminuer, s’apaiser (abattre)","t":"« Abattre »: the storm is beaten down. The storm abated."},{"w":"acumen","p":"n.","m":"Keen insight; sharp judgment.","e":"Latin <i>acumen</i> (point, sharpness), from <i>acuere</i> (to sharpen).","f":"perspicacité, flair","t":"Acus = needle: a mind sharp as a point. Business acumen = le sens des affaires."},{"w":"adulterate","p":"v.","m":"To make impure by adding inferior substances.","e":"Latin <i>adulterare</i> (to corrupt), from <i>ad</i> + <i>alter</i> (other).","f":"frelater, altérer","t":"Adding something other (alter): watered-down wine is adulterated, « frelaté »."},{"w":"alleviate","p":"v.","m":"To make suffering less severe.","e":"Late Latin <i>alleviare</i>: <i>ad</i> + <i>levis</i> (light).","f":"soulager, alléger","t":"Levis = léger: alleviate = « alléger » the pain."},{"w":"approbation","p":"n.","m":"Approval or praise.","e":"Latin <i>approbatio</i>, from <i>approbare</i> (to approve): <i>ad</i> + <i>probare</i> (to test, find good).","f":"approbation","t":"Same as « approbation ». Opposite: opprobrium."},{"w":"articulate","p":"adj. / v.","m":"Expressing oneself clearly; to express clearly.","e":"Latin <i>articulatus</i> (jointed), from <i>articulus</i> (small joint). Speech divided into distinct parts.","f":"qui s’exprime bien; articuler, formuler","t":"Joints (articulations) make movement clear; articulate speech is clearly jointed."},{"w":"aver","p":"v.","m":"To state or assert to be true.","e":"Old French <i>averer</i>, from Latin <i>ad</i> + <i>verus</i> (true).","f":"affirmer, avérer","t":"Aver = declare it « avéré », true (verus)."},{"w":"bombastic","p":"adj.","m":"High-sounding but with little meaning; pompous.","e":"From <i>bombast</i>, cotton padding for clothes, from Medieval Latin <i>bombax</i> (cotton). Padded speech.","f":"grandiloquent, pompeux","t":"Bombast = cotton stuffing: speech padded with fluff."},{"w":"chicanery","p":"n.","m":"Trickery to achieve a goal.","e":"French <i>chicanerie</i>, from <i>chicaner</i> (to quibble).","f":"chicane, manœuvres","t":"French « chicane »: legal tricks and quibbles."},{"w":"circumspect","p":"adj.","m":"Cautious; unwilling to take risks.","e":"Latin <i>circumspectus</i>: <i>circum</i> (around) + <i>specere</i> (to look).","f":"circonspect, prudent","t":"Same as « circonspect »: looking all around before acting."},{"w":"clamor","p":"n. / v.","m":"A loud, insistent demand or noise.","e":"Latin <i>clamor</i> (shout), from <i>clamare</i> (to cry out).","f":"clameur, réclamer à grands cris","t":"« Une clameur »: the crowd shouting for something."},{"w":"compliant","p":"adj.","m":"Inclined to obey; meeting rules.","e":"From comply, Italian <i>complire</i>, from Latin <i>complere</i> (to fill up, complete).","f":"docile, conforme","t":"Compliant with the rules = « conforme ». Compliance team."},{"w":"connoisseur","p":"n.","m":"An expert judge in matters of taste.","e":"Old French <i>connoisseur</i> (modern <i>connaisseur</i>), from Latin <i>cognoscere</i> (to know).","f":"connaisseur","t":"Straight from French « connaisseur »."},{"w":"covert","p":"adj.","m":"Not openly acknowledged; secret.","e":"Old French <i>covert</i> (covered), past participle of <i>covrir</i> (to cover).","f":"secret, caché, clandestin","t":"Covered = « couvert ». Covert ops. Opposite: overt (ouvert)."},{"w":"desiccate","p":"v.","m":"To dry out completely.","e":"Latin <i>desiccare</i>: <i>de-</i> + <i>siccare</i> (to dry), from <i>siccus</i> (dry).","f":"dessécher","t":"Siccus = sec: « dessécher »."},{"w":"deterrent","p":"n.","m":"Something that discourages an action.","e":"Latin <i>deterrere</i>: <i>de-</i> (away) + <i>terrere</i> (to frighten).","f":"moyen de dissuasion","t":"Frighten away (terrere, as in terreur). Nuclear deterrent = « force de dissuasion »."},{"w":"dissent","p":"n. / v.","m":"Disagreement with official opinion.","e":"Latin <i>dissentire</i>: <i>dis-</i> + <i>sentire</i> (to feel).","f":"dissidence, désaccord","t":"Feeling apart: a dissenting opinion. « Dissension »."},{"w":"divest","p":"v.","m":"To deprive or rid oneself of something.","e":"Medieval Latin <i>divestire</i>: <i>dis-</i> + <i>vestire</i> (to clothe). To undress.","f":"se défaire de, céder","t":"Un-dress: divesting a business unit = taking off a piece of clothing (vêtement)."},{"w":"efficacy","p":"n.","m":"The ability to produce the intended result.","e":"Latin <i>efficacia</i>, from <i>efficere</i> (to accomplish).","f":"efficacité","t":"« Efficacité » of a drug in a clinical trial."},{"w":"eloquent","p":"adj.","m":"Fluent and persuasive in speech.","e":"Latin <i>eloquentem</i>, from <i>eloqui</i>: <i>e-</i> (out) + <i>loqui</i> (to speak).","f":"éloquent","t":"Same as « éloquent »: speaking out."},{"w":"epitome","p":"n.","m":"A perfect example of a type.","e":"Greek <i>epitomē</i> (abridgement), from <i>epitemnein</i> (to cut short).","f":"incarnation, quintessence","t":"Once a summary; now the essence condensed. Not « épitomé » (summary) in modern use."},{"w":"eulogy","p":"n.","m":"A speech praising someone, especially at a funeral.","e":"Greek <i>eulogia</i> (praise): <i>eu</i> (well) + <i>logos</i> (speaking).","f":"éloge funèbre","t":"Eu-logos = speaking well of someone. « Éloge »."},{"w":"explicit","p":"adj.","m":"Stated clearly; leaving nothing implied.","e":"Latin <i>explicitus</i> (unfolded), from <i>explicare</i>: <i>ex-</i> + <i>plicare</i> (to fold).","f":"explicite","t":"Unfolded fully. Opposite: implicit (folded in)."},{"w":"facilitate","p":"v.","m":"To make easier.","e":"French <i>faciliter</i>, from Latin <i>facilis</i> (easy).","f":"faciliter","t":"Same as « faciliter »."},{"w":"fervid","p":"adj.","m":"Intensely enthusiastic; passionate.","e":"Latin <i>fervidus</i>, from <i>fervere</i> (to boil).","f":"fervent, ardent","t":"Boiling: same root as « ferveur »."},{"w":"guile","p":"n.","m":"Sly or cunning intelligence.","e":"Old French <i>guile</i> (deceit), probably Frankish; related to English <i>wile</i>.","f":"ruse, astuce","t":"Guile = wiles = ruse. Guileless = without it."},{"w":"gullible","p":"adj.","m":"Easily persuaded to believe something.","e":"From <i>gull</i> (to dupe), perhaps from the seagull, a bird that swallows anything.","f":"crédule, naïf","t":"A seagull swallows whatever is thrown. « Crédule »."},{"w":"homogeneous","p":"adj.","m":"Of the same kind; uniform.","e":"Greek <i>homogenēs</i>: <i>homos</i> (same) + <i>genos</i> (kind).","f":"homogène","t":"Same as « homogène »."},{"w":"implicit","p":"adj.","m":"Implied though not stated; absolute (implicit trust).","e":"Latin <i>implicitus</i> (entwined), from <i>implicare</i>: <i>in-</i> + <i>plicare</i> (to fold).","f":"implicite; absolu","t":"Folded inside. Opposite: explicit."},{"w":"inconsequential","p":"adj.","m":"Not important or significant.","e":"<i>in-</i> + Latin <i>consequentia</i>, from <i>consequi</i> (to follow).","f":"insignifiant, sans importance","t":"Nothing follows from it: no consequences."},{"w":"indeterminate","p":"adj.","m":"Not exactly known or established.","e":"Latin <i>indeterminatus</i>: <i>in-</i> + <i>determinare</i> (to limit), from <i>terminus</i> (boundary).","f":"indéterminé","t":"No boundary drawn: « indéterminé »."},{"w":"intractable","p":"adj.","m":"Hard to control or solve.","e":"Latin <i>intractabilis</i>: <i>in-</i> + <i>tractare</i> (to handle).","f":"insoluble, réfractaire","t":"Can’t be handled or pulled (tractor). An intractable problem."},{"w":"lavish","p":"adj. / v.","m":"Sumptuous; to give generously.","e":"Old French <i>lavasse</i> (downpour), from <i>laver</i> (to wash). A flood of something.","f":"somptueux, prodiguer","t":"A downpour (« lavasse ») of gifts. Lavish praise."},{"w":"loquacious","p":"adj.","m":"Talkative.","e":"Latin <i>loquax</i>, from <i>loqui</i> (to speak).","f":"loquace","t":"Same as « loquace »."},{"w":"nascent","p":"adj.","m":"Just beginning to develop.","e":"Latin <i>nascentem</i>, from <i>nasci</i> (to be born).","f":"naissant","t":"« Naissant »: just born. A nascent industry."},{"w":"onerous","p":"adj.","m":"Burdensome; involving heavy effort.","e":"Latin <i>onerosus</i>, from <i>onus</i> (burden).","f":"lourd, pesant (onéreux = costly)","x":"Faux ami","t":"Onus = burden. French « onéreux » means expensive; English onerous means heavy work."},{"w":"opprobrium","p":"n.","m":"Harsh public criticism; disgrace.","e":"Latin <i>opprobrium</i> (reproach): <i>ob</i> (against) + <i>probrum</i> (shameful act).","f":"opprobre","t":"Same as « jeter l’opprobre sur ». Opposite of approbation."},{"w":"overt","p":"adj.","m":"Done openly; not hidden.","e":"Old French <i>overt</i> (open), past participle of <i>ovrir</i> (to open), now <i>ouvrir</i>.","f":"manifeste, ouvert","t":"Overt = « ouvert ». Covert = « couvert »."},{"w":"paradox","p":"n.","m":"A seemingly self-contradictory statement that may be true.","e":"Greek <i>paradoxos</i>: <i>para</i> (contrary to) + <i>doxa</i> (opinion).","f":"paradoxe","t":"Against common opinion (doxa). Same as « paradoxe »."},{"w":"partisan","p":"adj. / n.","m":"Strongly biased towards a party or cause.","e":"French <i>partisan</i>, from Italian <i>partigiano</i>, from <i>parte</i> (part, faction).","f":"partisan","t":"Same as « partisan »: taking one party’s side."},{"w":"plethora","p":"n.","m":"An excess; a large amount.","e":"Greek <i>plēthōrē</i> (fullness), from <i>plēthein</i> (to be full).","f":"pléthore","t":"« Pléthore de candidats »: an overflow."},{"w":"propriety","p":"n.","m":"Conformity to accepted standards of behaviour.","e":"Old French <i>propriete</i>, from Latin <i>proprietas</i> (appropriateness), from <i>proprius</i> (one’s own, proper).","f":"bienséance, convenance (≠ propriété)","x":"Faux ami","t":"Not property! Propriety = « les convenances », what is proper."},{"w":"tacit","p":"adj.","m":"Understood without being stated.","e":"Latin <i>tacitus</i> (silent), from <i>tacere</i>.","f":"tacite","t":"Same as « tacite »: « reconduction tacite »."},{"w":"tangential","p":"adj.","m":"Only slightly relevant; diverging.","e":"Latin <i>tangentem</i>, from <i>tangere</i> (to touch). A tangent only touches the circle at one point.","f":"accessoire, secondaire","t":"Going off on a tangent: barely touching the topic. « Partir dans une digression »."},{"w":"tenuous","p":"adj.","m":"Very weak or slight.","e":"Latin <i>tenuis</i> (thin).","f":"ténu, fragile","t":"Same as « ténu »: a thin thread of logic."},{"w":"veracity","p":"n.","m":"Truthfulness; accuracy.","e":"Medieval Latin <i>veracitas</i>, from <i>verax</i> (truthful), <i>verus</i> (true).","f":"véracité","t":"Same as « véracité ». Vrai."},{"w":"verbose","p":"adj.","m":"Using more words than needed.","e":"Latin <i>verbosus</i>, from <i>verbum</i> (word).","f":"verbeux","t":"Same as « verbeux »: too many verbs/words."},{"w":"volatile","p":"adj.","m":"Liable to change rapidly and unpredictably.","e":"Latin <i>volatilis</i> (flying), from <i>volare</i> (to fly).","f":"volatile, instable, explosif","t":"Flying away (voler): volatile markets, a volatile temper."},{"w":"wary","p":"adj.","m":"Cautious about possible dangers.","e":"Old English <i>wær</i> (watchful). Germanic, related to aware and beware.","f":"méfiant, prudent","t":"Beware → wary. Méfiant."},{"w":"zealous","p":"adj.","m":"Having great energy for a cause.","e":"Greek <i>zēlos</i> (ardour, jealousy), via Latin <i>zelus</i>.","f":"zélé","t":"Same as « zélé ». Zealots were fervent rebels in Judea."}]}];
